rows["24:999904860"]="왜 뒤집어있어요?"
rows["250:1172842231"]="그래! 확실히 죽었군... 그렇다면 너... 아니 너희 모두 새 왕이 되는 거야! 왕! 이제 고르독은 네 거야. 왕 노릇이 어떤 건지 알고 싶으면 나하고 얘기해! 난... 왕의 비서였다! 맞아, 나를 약삭빠른 미즐이라고 부르는 것도 그 때문이지!"
rows["250:1452258967"]="< 당신의 새끼는 실망스러운 얼굴로 당신을 쳐다보고 다른 새끼와 놀고 있다는 것을 알 수 있습니다.>$B$B< 한 번에 한 번만  ⁇ 아들 놀 수 있습니다. 이 애를 가지고 캐치!을 하기 전에 현재  ⁇ 아들 돌려달라고 안리 장에게 말해주세요.>"
rows["250:1489514798"]="좋아. 서큐버스는 남성 적들을 매혹시켜 교란을 유도할 수 있을 뿐만 아니라 상당한 타격도 입힐 수 있지. 하지만 방어력이 약해서 방패로는 거의 쓸모가 없어."
rows["250:1570552898"]="만약 당신이 Cenarion Circle가 어딘가에 보관한 정보를 찾고 있다면, 나에 대해 이야기해야 할 사람이야$B$B어떻게 작동하는지 보셨나요?"
rows["250:1596481377"]="난 방랑 섬에서 자랐습니다. 그 곳에는 공간이 너무 제한적이어서 사냥할 곳이 없었고,$b$b하지만 여기... 여기 큰 무산과 늑대와 모든 종류의 맹수들이 있습니다."
rows["250:1626510067"]="여러분은 확실히 그 가치를 증명했겠지만, 자료는 비용 없이 제공되는 것은 아닙니다.$b$b고야 부인과 일 할 수 있겠지만, 싸게 되지 않을 거야.$b$b한 번의 공포 크리스탈만 설치할 수 있다는 것을 기억하세요"
rows["250:1684658331"]="이 룬스톤 은 에버스온 의 땅 을 스컬지 에 의해 오염 되지 않도록 보호 합니다. 서부 룬스톤 은 오래전 실패 했으므로, 우리 는 그 주변 에 있는 땅을 태워버려야 합니다.$B$B내가 살아 있는 동안 남은 러닝스톤들이 우리를 실패하게 만들지 않을 거야"
rows["250:1919526671"]="너무나도 가슴 아픈 결정이었지만... 그 모든 파괴, 터무니없는 학살은 끝이 나야만 했다. 그러나 말리고스의 죄악과 상관없이 나는 그의 죽음을 애도할 것이다. 그도 한때는 이 세계의 수호자였지. 오늘, 한 강력한 존재가 떠났다."
rows["250:201637962"]="정식선수 마리엘 트루하르트는 우리에게 대회의 많은 일을 감독할 의무를 맡겼습니다. 불행히도 그녀는 선리버들에게 같은 의무를 맡겼고, 즉 우리가 그 바보들이 만든 문제를 해결하기 위해 두 배 더 열심히 노력해야 한다는 것을 의미합니다!"
rows["250:2047535473"]="그럼, 당신은 강력한 Exodar을 복구하는 데 도움이 되려고 합니다? 나는 Exodar이 다시 완전히 작동하기까지 몇 년이 걸릴 것이라고 들었습니다. 당신은 두 시간. 그냥 농담입니다. 우리의 엔지니어는 트레이더의 레벨의 낮은 수준에 위치하고 있습니다. 빛를 선택하십시오."
rows["250:2072451167"]="우리 새로운 손님들은 우리의 일을 제한하고 있지만, 집단살인 시도가 일어나면 조심해야 하는 것은 당연한 일이지만, 시간이 지나면 그들이 푸트레스가 불행한 이상이었다고 확신하게 될 수도 있고,"
rows["250:2104099019"]="보렌살과 그 부하들의 변절은 그때까지 캘타스의 군대가 입었던 어떤 피해보다도 큰 손실이었습니다. 더구나 이들은 평범한 블러드 엘프들이 아니었죠. 캘타스를 따르던 최고의 학자들과 마법학자들 중 상당수가 보렌살의 영향을 받아 마음이 흔들렸습니다."
rows["250:380383365"]="항상 3손가락 할인 받을 수 있어 손목에 걸려서 훔치는 걸 잘 못하면 肋骨 사이에  ⁇ 어 넣고 손목에 걸려$B$B숙련된 손은 일정임금보다 더 가치있죠"
rows["250:454296134"]="빛! 다른 사람 들 의 복지에 관심 을 기울인 사람 이 있다는 것 은 축복 이다. 이와 같은 때 에 우리 는 얻을 수 있는 모든 도움 이 필요 합니다. 누스는 첫 번째 도움 의 방법 에 대해 သင္ 을 훈련 할 수 있습니다. 그녀는 크리스탈 홀 의 크리스탈 동굴 근처 에 있습니다. 빛 이 당신과 함께 하십시오."
rows["250:634208141"]="이 악마는 공허방랑자라고 알려져 있지. 힘과 맷집이 대단해서 방어용으로 이상적이야. 공허방랑자가 먼저 적을 공격하게 한 뒤, 녀석을 방패 삼아 자네의 주문이나 능력을 사용하게."
rows["250:65425641"]="우리의 이성 기술력은 미묘한 본질을 이전에는 상상할 수 없었던 방식으로 변형시킬 수 있습니다. 우리는 작은 수수료로 주머니 차원에서 물건을 보관할 수 있습니다.$B$B내가 조사할 게 없는 한?"
rows["250:862624728"]="세티넬 군대의 세력은 칼림도어 전체에서 호드를 억제합니다. 전쟁은 계속되고 잿빛 골짜기와 스톤탈론에도 우리 세력이 필요합니다. 남아있는 야생 동물을 보호하고 적들이 더 많은 발자국을 확보하지 않도록 말이죠."
rows["251:1029910804"]="아이언포지 공격당하고 있어 도시 방어할 만큼 강해$B$B마그니 왕은 도시를 완전히 대피하라고 명령했고, 내가 그 일을 처리하도록 지시했다."
rows["251:1400896631"]="당신은 지위를 이용해 슬픔에 잠긴 소년에게 검을 되찾아 오도록 했지. 이제 성인이 된 소년의 마음속에는 복수심과 증오만이 가득할 뿐이오! 대체 왜? 그런데 5년 전이나 지금이나 당신은 그 검을 만져보지도 못하고 있지 않소!"
rows["251:1461257481"]="울음만 빼면 모든 전쟁 재물이 실리투스 센라리오네 포크로 옮겨지고 있고 마지막은 하루도 안 돼서"
rows["251:1567136111"]="난 내 음식을 원료로 먹지만, 네가 좋아하는 데니카가 요리하면 불을 붙이는 방법을 보여줄 수 있어"
rows["251:1583702045"]="타워 포인트 이스트는 남쪽에서 전투장과 호드 영토 사이의 경로를 지킨다.$B$B동부 프로스트울프 타워는 프로스트울프는 빌리지와 프로스트울브 키프 사이의 게이트를 보호합니다.$B$B이 둘 다 통제됩니다."
rows["251:1698647339"]="황제 비지어 조로크 |cFFFF0000|Hspell:122336|h[소닉 링]|h|r 능력으로 멸망했다. 황제 비지르 조로크가 캐스팅을 시작할 때 |cFFFF0000|Hspell:122496|h[조명]|h|r"
rows["251:1912286430"]="이 가게의 비시 와블본크는 다고 훈련도 할 수 있습니다. 스톰윈드, 힌디어, 에크소다르, 다르나서스 난 칼투기 한 번도 안 했어"
rows["251:1953804824"]="이봐요. 너희 사람들은 그들의 조상들을 존중하고, 너희는 땅을 소중히 여기고, 우리는 많은 공통점을 가지고 있다! 아, 하지만 나는 너희 조상들이 유목민이었음을 보고 있지만, 우리가 판다레인은 가옥과 가정의 편안함을 선호한다. 우리 가운데 여행자들이 거의 없을 것이다."
rows["251:403866963"]="지금 보시는 것은 세계에서 가장 최신의 광산입니다. 산 아래의 광물을 찾기 위해 산 아래로 터널을 파는 데는 돌연변이가 있습니다. 우리는 산 전체를 옮겼습니다. 이제 우리는 땅으로부터 귀한 금속을 뽑을 수 있습니다."
rows["251:512327417"]="타워 포인트 이스트는 남쪽에서 전투장과 호드 영토 사이의 경로를 지킨다.$B$B이 기관은 얼라이언스동부 프로스트울프 타워는 프로스트울프는 마을과 프로스트울프를 보호한다.$B$B얼라이언스에 의해 통제됩니다."
rows["251:515167241"]="모든 것이 연결되어 있다는 것을 기억하세요. 만약 동물들이 땅에서 사라진다면 우리 종들은 큰 외로움을 겪어 죽었을 것입니다. 아제로스 그 안에 사는 모든 자들을 멸망케 하리라"
rows["251:573067040"]="왕자는 거대한 힘의 악마를 거대한 힘의 현장의 뒤에서 감옥에 갇히도록 음모했습니다. 기둥들은 그 현장에 숨겨진 에너지를 송신하여$B$B감옥에서 임몰타르는 엘드레 타라스 주민들에게 배터리 역할을 할 것입니다."
rows["251:820298754"]="안녕하세요! 우리는 해상에서 그 쓸모없는 해적들에 의해 봉쇄되고 있습니다! 당신은 그들에게 몇 개의 폭탄을 던지면서 우리를 도울 수 있다고 생각합니까?!$B$B훔친 제펠린이 거의 왔어... 이제 들릴 것 같네요."
rows["251:987693959"]="로타르의 아들들에게 사람을 빼앗을 수는 있지만, 아들들을 빼앗을 수는 없다.$B$B<위공이  ⁇ 다>$B$B설명하기 힘들지만 지금은 명예회관에 있는 게 아니란 것 같네요$B$B어쩌면 더 큰 무언가의 일부가 될 수 있을지도 몰라"
rows["252:1001042222"]="역사사의 일은 끝나지 않습니다. 항상 중요한 일이 일어나고 있습니다.$B$B이미 많은 것을 썼지만, 아직 배울 일이 많아요!"
rows["252:1066955705"]="고성장의 아라니어 스타싱거는 미스터리 재조작의 마스터입니다. 당신이 그를 설득하면 당신을 도울 수 있습니다.\010그는 종종 북서부 달라란에 있는 마구스 무역 거래소 바로 밖에 있는 Simply Enchanting의 사람들과 그의 공예에 대해 논의하는 것을 발견할 수 있습니다."
rows["252:1414572546"]="어렸을 때 저는 맥주 제작사가 되고 싶었습니다. 완벽한 음료와 맛을 얻기 위해 다양한 화학 물질을 섞고 싶었습니다.$b$b훈련 중에 그들은 항상 내 음료가 너무 심하다고 말했어요.$b$b그래서 저는 녹음으로 들어가게 되었습니다. 그 당시엔 논리적 전환이 된 것 같았습니다."
rows["252:158950450"]=" ⁇ 은, 백 호랑이는 북쪽의 추운 바람을 지키고 있습니다.$B$B오늘날 그는 그 나라의 최고의 챔피언들을 일련의 시험으로 시험하려고 합니다.$B$B당신이 스스로가 가치가 있다고 생각한다면 북쪽으로 가서 백 호랑이의 사원으로 도전해 보세요!"
rows["252:1645857697"]="네! 발 을 굳게 지키십시오. 여러분의 동군들에게 도움을 주십시오. 그리고 우리 연합한 힘으로 이 악마들을 이길 것입니다. 희망에 치열하게 집착하고, 무기를 단단히 붙잡고, 빛이 어둠을 뚫고 내일 새벽까지 빛날 것을 신뢰하십시오."
rows["252:1758571757"]="\"노이인 스톰윙은 머리를 흔들고 있다\".$B$B레지온이 한쪽이고 이리던의 하자가 다른 쪽으로 있으면, 우리는 요새를 방어하기 위해 필요한 모든 것을 가져갈 것입니다."
rows["252:1810878043"]="전 신도들의 보상이 자신의 행운을 생각해보고 주변 사람들과 공유하는 시간이라고 들었습니다.$B$B우리는 이 세상과 그 용기 있는 주민들을 발견한 것이 행운이고, 우리가 우리의 지식과 힘을 새로 발견한 동맹국들에게 제공한다는 것은 적절합니다."
rows["252:2127051961"]="저는 '부러진' 중 한 명입니다. 이것이 당신을 괴롭히지 않기를 바랍니다. 부러진거나 마비된 우리는 우리 사회에서 어떤 사람들이 우리를 비웃을 수 있는 것을 견뎌야 합니다. 이 세상의 요소들과 더 나은 이해와 소통이 중요합니다."
rows["252:25654524"]="잘못된 투자를 하는 것에 대해 이야기 해!$B$B왈타락의 마법 책에서 블랙마켓에서 꽤나 많은 돈을 벌었는데, 그가 자신의 재산을 훔치지 못했을 때 너무 친절한 것은 아쉽지만, 그 불쌍한 놈은 몇 달 동안 죽은 후에도 우리를 잡았어!"
rows["252:285488493"]="마법을 사용하는 모든 적들을 상대할 때는 이 무시무시한 짐승이 가장 유용할 거야. 이제 약간 다른 녀석을 살펴볼까? 자네의 여행을 도와주고 앞으로 여정을 훨씬 편하게 해줄 친구지. 자, 지옥마를 살펴보자고."
rows["252:535649263"]="내 로켓 부츠를 수리해야 해  \010오, 하지만 방향이 필요해요... 그냥 왜성 구역으로 가세요, 뒤쪽으로는 리얼리아마 스파크스피indle를 찾을 겁니다."
rows["252:67843514"]="이제 그것은 착용할 가치가 있는 철 조각입니다. 형태와 기능 소년/자녀, 나는 인상적입니다. 한 번만 그것을 일치 한 본 적이 있습니다. 그레이트 포지에서 마스터의 Grumnus Steelshaper. 나는 그 이후로 몇 가지 배운 것 중 하나를 내걸고 있습니다. 아마도 당신에게 가르쳐 줄 수 있습니다."
rows["252:906841710"]="이 책 은 피부 작업 에 대한 당신 의 기술 을 알고 있으며 선택 을 제안 합니다. 하지만 경고 를 해 보십시오. 한 가지 를 선택 할 수 있으며, 그렇게 한 후에는 당신 의 생각 을 바꾸지 않을 것 입니다!"
rows["253:1082498120"]="저는 아버지나 어머니를 알지 못했는데, 오르그림은 그들에게 많은 이야기를 해주었고, 드레노르에서의 모험을 이야기했습니다. 그는 제 가장 위대한 선생님이자 절친한 친구였습니다."
rows["253:1093320434"]="이곳에 자주 오신 것 같은데, 일을 마친 후에 만나지 못하고 서로 계속 엇갈린 것 같네요.$B$B저 때문인가요?$B$B<일부러 기운을 내는 카티에>$B$B어쨌거나, 제가... 우린 당신이 하늘경비대를 위해 해 준 모든 일에 정말 감사드린다고 얘기하고 싶었답니다!"
rows["253:1332309263"]="난 이곳도 싫고 여기 사람들도 싫습니다! 이거 해라! 저거 해라! 그래, 이제 내가 농부란 말이지요? 그럼 수확도 해야겠군요? 언젠가 이곳이 공동묘지가 되어서 시끄러운 자들이 죄다 묻혀 버렸으면 좋겠군요!"
rows["253:147451062"]="맥주 페스트는 맥주와 음식에 관한 것인데, 우리가 제공하는 것보다 더 좋은게 되지 않습니다. 내가 거짓말을 하고 있다고 생각하세요? 우리가 가진 맛있는 맥주, 소시지, 프레스엘, 치즈들을 보세요. 여러분은 보실 겁니다."
rows["253:1504335108"]="고마워요, 필사자, 꿈으로 돌아가기 전에 한 가지만 드릴 수 있습니다.$B$B제브림의 주인 알츠린의 문이 당신의 길을 막고 있어 내가 파괴의 도구로 작용할거야 문이 열릴거야"
rows["253:1714610051"]="내 천재는 상자 안에 갇혀서는 안 돼!$B$B잠깐, 이건 아즈하라가 아니냐? 이 곳은 뭐야?$B$B내 생각의 절반은 무역 왕자와 함께 갈 것인데 다른 절반은  ⁇ 기 달걀의 무기화 방안을 고려하고 있습니다!"
rows["253:1921846425"]="환상이 필요해요?$B$B만약 당신의 탐구 중 당신의 환상이 흔들리면, 내게 돌아가서$B$B만일 너희가 실패하면 포기하지 말라 내게로 돌아가라 내가 너희를 도울 것이요 너희가 목표를 이루기 전까지"
rows["253:1970973415"]="많은 포세이큰하지만, 만약 당신이 축하에 참여하기로 결정한다면, 칼림도어- 위층의 왕좌실에는 드루이드들이 있을 겁니다 언더시티 그쪽은 당신을 데려다 줄 것입니다."
rows["253:208384936"]="얼음 늑대 보호소는 알테락밸리의 남쪽 끝에 위치하고 있으며 동명의 오크 부족의 고향인 얼음 늑대 마을을 보호합니다. 호드 알테락밸리의 영토는 이 하나의 권력으로부터 비롯되었습니다.$B$B프로스트울프 케이프는 파괴됐고 재건중입니다."
rows["253:2089918556"]="정말 멋지네요, 모든 조명을 보세요!$b$B무슨 일이 벌어지고 있다고 생각하니?$b$b와아아이트 - 그게 류랑인가요?$b$b그 거북이는  ⁇ 진수야, 그건 그렇고, 작은 아기여자 섬의 동상이야$b$B우린 집에 왔어, 첸 삼촌!$b$b- 뭐, 그런 것 같군"
rows["253:577680162"]="만약 숙소가 필요하다면, 돌불 숙소는 여러분이 있어야 할 곳입니다. 아이언포지의 입구에서 왼쪽으로만 찾을 수 있습니다.  $B$B저쪽으로 가면, 텐카드 준비하라고 말해"
rows["253:798797874"]="$p레이  ⁇ 을 만나서 영광입니다$b$b떠돌아다니는 섬의 여행자들은 우리에게 공포스러운 Thunder King에 대한 많은 이야기를 들려주었습니다. 우리는 조심스럽게 여기서 진행해야 합니다. 전설을 믿으면 그는 잔인한 것처럼 똑똑했습니다."
rows["254:100159793"]="한 번 부모님은 우리 고향 남쪽에서 살던 이상한 털이 있는 사람들에 대해 이야기 했습니다.$b$b내가 얼마나 잘못됐는지 이제 알아, 그들이 이 세상을 돌아다니면서도 이런 걸 볼 수 있었으면 좋겠어."
rows["254:1016875344"]="처음 등장한 그룹인 트롤들은 우리를 전혀 신경쓰지 않았고 우리 가족들을 쫓아냈습니다.\010그 다음 에는 용병 들 이 우리를 포로 로 잡았고, 우리 가 집 을 훔쳐갔으며, 저항 한다면 죽게 될 것 이라고 위협 하였다."
rows["254:102294918"]="토림은 지쳤고 가장 사랑하는 동맹군인 얼음 거대들을 공격했습니다.$B$B그 이유 중 하나는 오늘날까지 이 땅이 하이드니르와 호디르의 아들 사이의 전쟁으로 찢어지고 있고 토림이 폭풍의 성전으로 추방되는 이유 중 하나입니다."
rows["254:1036325581"]="젠타브라가 웃고 있습니다.$B$B우린 소문을 퍼뜨리죠, 자라잔과 다른 사람들을 쫓아내지 마세요.$B$B아니, 우린 몇 년 전에 배운 새로운 기술이지만 어떤 면에서는 전화에 대한 응답을 준비하는 데 평생을 보냈습니다."
rows["254:1176778284"]="알레고르네가 만든 음식들은 죽기 위해서다 그는 항상 공예의 테라스에서 새로운 맛을 준비하는 데 바쁘다  \010이제, 만약 당신이 상관하지 않는다면, 저는 사라진 게슴의 발진을 조사해야 합니다. "
rows["254:1249510120"]="자, 여기 오래 머물면 결국 조지오 볼레로에 대한 입소문을 듣게 될거야. 그는 몇 달 동안 트렌드를 설정하고 있어."
rows["254:1308970087"]="우리는 이 비참한 과제를 고스란히 시작하여 우리의 사안이 실패하지 않도록 할 것입니다. 여러분의 형제들과 한때 열렬한 적들의 도움을 환영합니다. 우리 모두가 연합된 힘으로 함께 앞으로 나아갈 것이며 오늘 승리를 알 수 있습니다."
rows["254:1430209729"]="빛의 대성당에서 안젤라 라이펠드의 감시 아래서 초급을 배울 수 있는 더 좋은 곳이 없습니다.  \010그곳을 가기 위해서는 노란색 지붕이나 대성당의 높은 탑을 찾아보세요."
rows["254:1452596610"]="마이스가 Buliwyf의 전문품이고, 그는 어딘가에서 이 가게에 서 있고, 그 중에서도 훈련 기술을 가지고 있지요."
rows["254:1632389381"]="|cff0000ff급 1:|r\010  브루스: $7427w-$7428w\010  비안 오브 Volatile: $7429w-$7430w\010  고레도미: $7431w-$7432w\010  던전 마스터 비샤: $7433w-$7434w\010|cff0000ff급 2:|r\010   ⁇ : $7443w-$7444w\010  키라크: $7453w-$7454w\010  프랜 & 리도: $7441w-$7442w\010  쿠라카 왕: $7479w-$7480w"
rows["254:1771019103"]="|cff0000ff급 1:|r\010  브루스: $7363w-$7364w\010  비안 오브 Volatile: $7365w-$7366w\010  고레도미: $7367w-$7368w\010  던전 마스터 비샤: $7369w-$7370w\010|cff0000ff급 2:|r\010   ⁇ : $7379w-$7380w\010  키라크: $7389w-$7390w\010  프랜 & 리도: $7377w-$7378w\010  쿠라카 왕: $7415w-$7416w"
rows["254:2110557637"]="곧 다른 소환자들과 함께 오치윈의 그림자 迷宫에 들어가게 될 거야$B$B큰 소리로 부르게 되길 바랄게요."
rows["254:24269690"]="우리 중 가장 강한 놈들이 사냥을 하던 동안 타우라조를 공격했습니다 얼라이언스 나와 다른 사람들이 작은 아이들을 수송할 수 있는$B$B<타우엔은 아이들의 눈앞에서 울지 않으려고 노력한다.>"
rows["254:352635690"]="제 뒤에 있는 구구는 한때 아제로스에서 일어나는 일들을 엿볼 수 있었습니다.$B$B물론 카엘타스의 저주로 모든 것이 바뀌었지만, 고립된 세월 동안 많은 마법사들이 그 이미지에서 위로를 얻었습니다.$B$B기억하기 위해  ⁇ 어들었고, 잊기 위해  ⁇ 어들었습니다. "
rows["254:690421139"]="안녕하세요, 저는 스랑글스톤에서 낚시 능력을 시험하는 대회를 홍보하기 위해 왔습니다. 참가하기 위해서는 그곳에서 살아남기 위해 충분한 힘과 물고기를 물에서 끌어내기 위해 충분한 낚시 기술을 필요로 합니다.$B$B 나중에 더 자격을 갖춘 후에 다시 오세요!\010"
rows["254:762802011"]="그러나 우리는 무엇보다도 조화를 이루고자 애쓰는 이들이오. 우리 전사들은 필요할 때만 싸운다오. 사냥꾼들은 부족에 필요한 걸 공급하고, 나머지는 자신을 위해 쓰지. 주술사는 정령을 인도하고, 또한 정령과 우리를 이어 준다오."
rows["254:776650803"]="많은 사람들이 암흑과 잊혀진 예술으로 피 마술을 피하고 있습니다. 이 방법과 다른 많은 방법으로, 그것은 악마의 마술과 몇 가지 다른 특성을 공유합니다. 여기, 악마가 박힌 블랙 모라스의 유해에서, 우리는 우리의 피 연구가 번성할 것이라고 믿습니다."
rows["254:925140584"]="워터스피커 로서, 저는 많은 의식 을 수행 했습니다. 하지만 한 가지 의식 은 제가 결코 행하지 않았습니다. 즉 정신 부패 를 깨끗 하게 하기 위해서였습니다.\010이것은 고대 의식입니다. 전설의 날부터 우리가 필요로 하지 않았던 의식이죠.\010지금 필요해"
rows["255:1296288193"]="무슨 일이 없지?$B$B세계 각 지방 의 숙소 주부 들 은 각종 락락 과제 를 나눠 주며, 많은 도시 들 은 이시절 에 맞춰 장식 되어 있다. 또한, 저녁 에 언더시티 근처 에 와이커먼 축제 가 열린다."
rows["255:1345933775"]="만약 당신이 칼리트레쉬 전쟁왕에 도달하려면 메크진에어 스팀리거와 히드로맨스 테스피아를 물리쳐서 메인 챔버 접근 패널에 도달할 수 있어야 합니다.$B$B몇 개의 버튼을 눌러서, 방의 문이 바로 열릴 겁니다!"
rows["255:1826986563"]="내가 명령한 것은 죽은 흉기에 방해를 주는 일이야 우리 세력이 태양의 무장 장비를 차지할 수 있게 해$B$B우리는 $3233w 퍼센트로 목표에 도달했습니다."
rows["255:1959926699"]="멀고어 어린 시절부터 훈련 받고 황금 평야에서 자랐던 이 훌륭한 동물들은 더욱 더 훌륭한 말을 만들 것입니다! 제 선택지를 검색하여 우리 황새들이 왜 이 멋진 생물들을 의지하게 되었는지 직접 확인해 보세요!"
rows["255:1972685666"]="클라와 저는 이곳을 조사하고 있었는데 무젤렉은 우릴 공격했습니다.$B$B불행히도, 클라우는 그 당시 곰 모양으로 잡혔고 지금은 습지 주인에게 반려동물입니다.$B$B그를 구하기 위해 클라와 싸워야 할 것 같아"
rows["255:2066703856"]="이런 녀석을 볼 기회가 있었나 모르겠군그래. 이 악마의 말을 제어할 수만 있다면 훨씬 빠르게 여행할 수 있지. 하지만 제어하기가 어렵기 때문에 시도하기 전에 확실히 준비가 되어 있어야 하네."
rows["255:338038988"]="문이 내려갔고, 플레거워크에 들어가는 걸 막는 장벽이 열렸어요! 제 지미들은 크림슨 홀로 가는 장벽을 무너뜨리는 데 노력하고 있습니다. 그 물건이 내려지기까지는 $4939W일 정도가 걸릴 겁니다.$B$B들어가서 좀 꺼내 스컬지!\010"
rows["255:390053935"]="크라운 화학 회사를 대표하는 데 왔습니다$B$B선물, 일, 어쩌면 너한테는 작은 걸 찾고 있어?$B$B네가 필요로 하는 걸 내가 안받으면 우리 마스코트 퀴나 나 옆에 있는 사랑스러운 상인이 그러겠지"
rows["255:500894677"]="우리는 크레인의 지혜를 찾고 우리가 가진 비전을 설명합니다.$b$b맨티드, 맨티드가 우리 집들을 공격하고 벽을 뛰어넘고$b$b이런 꿈은 벽에 가까이 사는 것으로 예상됩니다.$b$B하지만 최근 그들은 매우 강박하고 있습니다."
rows["255:535107131"]="매일 새로운 것을 보관하고 오래된 것을 보관합니다. 때로는 지혜의 고대 서적입니다. 때로는 잉크 마스터가 만든 골짜기의 그림입니다.$b$b우리는 이 전통을 보존해 나가서 미래 세대가 우리의 성공과 실패를 통해 배울 수 있도록 합니다."
rows["255:545731803"]="빛의 형제단은 다른 어떤 집단의 능력도 넘어서 빛에 대한 공격을 근절할 수 있습니다. 우리는 이 죽은 자처럼 더러운 짐승들을 제거하기 위해 필요한 모든 조치를 취할 것입니다. 우리 길이 서있을 것입니다.$B$B우리 편이냐 아니면 반대편이냐?"
rows["255:558915039"]="우리는 이 점을 방어할 수 있었습니다.$B$B당신은 우리의 순위에 소중한 동맹을 모집하는데 성공했지만, 적은 계속 우리를 공격하고 있습니다.$B$B우리는 우리의 입장을 견디어야 합니다. 아니면 우리가 그렇게 열심히 싸웠던 것을 잃어야 합니다."
rows["255:590659908"]="영원한 꽃의 계곡$b$b누가 그 장갑이 이렇게 아름다운 장소를 파괴할 수 있다고 상상했을까?$b$b골든 로투스는 언젠가 모가이 이 땅을 되찾을 것이라고 두려워했지만 가로쉬의 자부심의 깊이를 과소평가한 것 같습니다."
rows["255:824847234"]="몇 년 전, 마그니 왕이 이 축제에 대해 제게 다가왔을 때 저는 그놈들이 브루페스트를 기억할 만한 행사로 만들 수 있다고 확신했습니다. 하지만 마그니는 우리가 집중해야 할 다른 과제가 있다는 것을 알고 있었습니다."
rows["255:852552258"]="여기로 발령나기 전에 진흙이 피부 미용에 얼마나 탁월한지 들은 적이 있지. 여기 와서 처음 나무뿌리에 걸려 넘어졌을 때, 그 탁월한 효과를 온몸으로 경험했어! 마력을 한 조각도 빌지 않고 그런 일을 할 수 있다니, 자연은 정말 놀랍기 그지없어."
rows["255:881264926"]="훈련 외에도 여러분들의 재능에 대한 지식을 여러분 마음에서 지워버릴 수 있는 능력이 있습니다. 이 절차를 거치면서 더 어려운 일이 되고, 따라서 더 비싸게 된다는 것을 경고하세요."
rows["255:888722149"]="낙스라마스의 언데드 야수 글루스는 식욕이 워낙 왕성해 산 자만으로는 놈의 허기를 달랠 수가 없다고 한다. 그래서 퓨진은 매일같이 놈에게 좀비 한 부대를 먹이로 준다더군. 전투에 내보내도 별 소용이 없는 약한 언데드를 재활용하는 셈으로 말이지."
rows["256:1286690801"]="이 마을의 유일한 보호자 나는  ⁇  스리 누입니다$B$B환영합니다. 하지만 제 명상으로 여러분들의 여행이 이 땅에 큰 변화를 가져올 것이라는 것을 알 수 있습니다."
rows["256:1410706101"]="하루 종일 농장에서 일하면 큰 식욕을 갖게 됩니다.$B$B내 말로는 들리지 않았지만, 대부분의 사람들은 시장을 통해 여자를 먹을 수 있습니다.$B$B대부분의 사람들은 좋아하는 요리를 가지고 있습니다. 당신이 요리하는 기술을 가지고 있다면, 그들은 당신의 요리를 시도하기를 갈망할 것입니다."
rows["256:1425667830"]="보통 우리는 많은 물품을 가지고 있지만 대부분의 물품은 비가 내리는 동안 파괴되지 않았습니다.$B$B하지만, 저는 건조한 연못의 생물들이 땅으로부터 온 비와 소금의 혼합물인 것을 확신합니다."
rows["256:1783976425"]="내 손에 충분히 안 들어있는 것처럼 광산의 이 왜들은 최근 카파라는 새로운 음료에 대해 미친 짓이 됐습니다.$B$B매일 아침 신선한 카파 컵을 가져오라고 주장합니다!$B$B내가 카파콩을 가져오려면 어떻게 해야 할지 아세요?"
rows["256:1890550058"]="<Anduin의 보디가드들은 당신이 왕자를 향해 나아갈 순간 더 가까워집니다.>$b$b괜찮아요, 제 친구와 대화를 나누고 싶네요. 우린 여기 전투 전선에서 멀어졌어요.$b$b와, 앉아!"
rows["256:1961718361"]="제 조카 리 리는 판다리아를 탐험하기 위해 너무 무자비하다. 하지만 사람은 결코 새로운 땅을 배우지 않습니다. 장소에서 장소에 달려서 말이죠.$b$b그것은 방황자 의 길 이다!"
rows["256:224745390"]="방금 업데이트를 받았어요 $2061w 가죽이 필요해 $2060w다른 사람들에게는 보고서는 우리가 모은 $2063w 이 중 $2064w 중형 가죽, 그리고 $2069w 우리 몸에서 $2071w 두꺼운 가죽 수요"
rows["256:329004947"]="제 가족은 현재 서부 플라그랜드즈에 있는 노스리지 목재 공장에서 일했습니다. 그들은 두마 가족에게 전념했고, 이제 붉은십자군 가 헤어트글렌과 함께 그 공장을 점령했습니다!$B$B저는 그 열렬한 사람들이 아제로스에서 지워질 때까지 쉬지 않을 것입니다."
rows["256:414744597"]="수백 년 전 이 공물은 왜성의 가장 위대한 기술적인 업적이라고 여겨졌는데, 각각의 공물의 공격에 대한 카운터들이 많아서,"
rows["256:46495734"]="<건축의 \"음\"은 당신 주변의 공중에서 나오는 것 같습니다. 당신의 팔에 있는 털이 일어나면서 귀에 울리는 소리입니다. 건축은 당신이 이해할 수 없는 언어로 당신에게 말하고 있습니다."
rows["256:907712784"]="토리움 형제단의 핵심요소$B$B아칸이트 결정은 풍부한 토륨 덩어리로부터 추출되며 강력한 화학자들의 알케미컬 실력으로 아칸이트 바가 탄생합니다.$B$B만약 당신이 광주를 찾는 사람이 아니라면 좋은 수학자도 찾아라!"
rows["257:1336126673"]="<블랑디는 잔에서 눈물을 흘린다>$B$B그래, 맞아요, 고한 샤만은 현장에서 Thundermar Wreckage를 되찾기 위해 싸우고 있어요.$B$B그가 떠나서, 그는 나를 여기 남겨두고, 썬더마르의 모든 샤머니나..."
rows["257:1633886897"]="작장이 아직 그 자신이 아니었습니다. 그의 여인이 남 사막에서 고고학적 발굴을 하던 중에 사라졌습니다. 흔적이 없이 사라졌습니다.$B$B일하러 갈 거야?"
rows["257:1728466617"]="새로운 전쟁 기계를 만들면 화이트에 꽤나 돈을 벌 수 있을 거 알아요  $B$B이전 몇 번은 완전히 안정적이지 못했지만, 비행기는 효과가 있는 폭탄 시스템을 개발할 수 있다면"
rows["257:1795758774"]="이 해적들에게 총을 팔고 부를 벌려줄게 좋았는데, 위즐은 저비용 엔지니어링 부품을 팔아먹어야 했습니다."
rows["257:185376296"]="카오스를 시작하면, 당신은 스스로 뒷문을 열지 못하겠지만 바의 고객들을 죽여서 경비원들이 문을 열어줄 수 있어야 합니다."
rows["257:1910729980"]="이 파괴된 황무지 속에서 갇혀서 우리는 살아남기 위해 최선을 다했습니다. 시간이 지남에 따라 우리는 새로운 악이 우리 주위에서 뒤틀린 황천더 사악한 암흑 오크보다 불타는 군단 이 일을 잡으려고 노력했던 아웃랜드."
rows["257:2006280065"]="약 20년 전, 얼라이언스 오크들을 영원히 없애는 희망으로 세계로 첫 탐험을 시작했습니다. 아제로스안전에 관한 것$B$B하지만 어떤 영혼들은 영원한 싸움에 갇혀 있습니다."
rows["257:261535575"]="공무원들한테는 믿을 수 없어 스톰윈드우리 군대의 대부분을 해외로 보내는데...$B$B서부 몰락지대에서 도둑들이 오고 동서쪽에서 거북이들이 침투하고 있는 만큼, 스톰윈드 자체는 포위되지 않은 것은 놀라운 일입니다."
rows["257:290253718"]="메디브에 관한 모든 문의는 탑 관장 모로스로 향해야 합니다. 저는 마스터의 사업에 대해 거의 모릅니다. 저는 몇몇 귀족들이 현재  ⁇ 홀에서 모로스와 청문회를 하고 있다고 믿습니다."
rows["257:307628918"]="디폴름은 최근 몇 년 동안 많이 변해왔고, 거의 알아볼 수 없습니다.$B$B하지만... 여기 저는 부패로부터 자유로워지고 있습니다. 고대 신들의 오염된 영향으로부터 자유로워졌습니다."
rows["257:390376597"]="영 은 눈 에 세심 히 보고 당신 의 손 을 잡아, 당신 의 몸 을 덥게 쏘아 올리고 거의 무릎 을 꿇게 됩니다.$B$B따뜻함이 지나갈수록, 당신은 당신의 존재 안에서 작은 비어성 정신이 존재하고 당신의 결단력을 강화합니다."
rows["257:391338004"]="구시가지의 돼지와 휘슬 타버너에서 일하는 훌륭한 요리사가 있는데, 그가 요리할 때 칼을 사용하는 것을 봤는데, 우리 둘 사이에선, 그는 항상 요리사가 아니었던 것 같아요."
rows["257:585456990"]="저는 이 단지와 관련된 필수적인 정보를 담는, 일종의 저장고 역할을 하도록 만들어졌습니다. 제 주요 기능에는 전방 방어 시스템의 상태 전달과, 이 단지에 수용해 두어야 하는 존재의 상태 평가가 포함되어 있습니다."
rows["257:747255272"]="도대체 얼마나 많은 보병이 시체가 되어 고향으로 돌아가야만 불타는 군단의 살인 부대로 뛰어드는 것이 자살 행위라는 것을 알겠는가? 그리고 마치 내 말을 이해한다는 듯이 그 큰 머리 좀 끄덕이지 말라!"
rows["258:1179585139"]="바시르의 크리스탈 포크를 사용하여 당신의 위축 조각들을 마법사의 불안정한 플럭으로 변형시킬 수 있습니다. 이 플럭들은 음주자를 더 지능적이고 더 심혈을 기울이고, 그들의 해로운 마법과 치유의 효과를 높여줍니다.$B$B아래에서 선택해"
rows["258:1751049152"]="전투 후 누가 우리 전사들을 붕대시켜야 한다고 생각하니"
rows["258:1774502660"]="이 벽 뒤에 얼마나 많은 지식이 숨겨져 있는지 누가 짐작할 수 있겠죠. 여기 있는 정보의 풍부함과$b$b어느 쪽을 듣고 싶으세요?"
rows["258:1820866755"]="제가 어렸을 때 다른 소년들은 모래와 상어를 얻기 위해 롯 모단 해저로 수영을 하다가 호수 표면에 갇혀서 다리를 부딪히고 있었지만, 우리는 그들과 합류할 수 없었습니다."
rows["258:1830192041"]="그런 얘기를 할 만큼 당신을 신뢰하지 않습니다.$b$b우리 민족이 겪은 고난과 우리가 지은 짐을 존중해야 합니다.$b$b아마도, 만약 당신이  ⁇ 니펠레मला 큰 명예를 안다면,"
rows["258:1838252443"]="그들은 내 말을 두려워하고 나를 예시로 삼고 있습니다. 유일의 진정한 신인 네프톨론을 조롱하는 것입니다.$B$B이 뱉어내라$B$B보복이 임해, 필사자, 어느 날  ⁇ 이사의 영광스러운 손은 새 재확에 대한 사늘처럼 불신자들을 휩쓸리라"
rows["258:1844939120"]="사이드는 현재 전투에 참여하고 있습니다. 사이드가 준비되어 있는지 확인해 주시기 바랍니다. 만약 그가 없다면 그는 또 다른 전투를 벌이고 있습니다."
rows["258:2146876152"]="우리는 Cenarion 드루이드들이 자연의 균형의 보호자입니다. 주요 포인트는 균형입니다. 요구될 때 우리는 결정적인 행동을 하기 전에 너무 오래 기다리지 않아야합니다. 아무도 당신에게 다른 것을 말하지 않도록하십시오. 특히 우리가 관찰만 하고 싶은 사람들!"
rows["258:51049390"]="빅글스워스 씨. 낙스라마스의 마지막 살아있는 생물인 이 고양이는 케일트루자드를 그의 필사적 삶과 연결하는 마지막 끈이라고 한다. 머리에 머리카락을 해칠 용기가 있는 사람은 스스로... 잠깐만, 그는 거기에 무엇을 하고 있는가?"
rows["258:615519634"]="일반적인 시간 관리는 시간의 수호자들만 있으면 충분합니다. 대부분의 평범한 사건은 우리 힘으로 처리할 수가 있지요. 제 말은 사소한 문제를 뜻하는 거랍니다. 예를 들어 도적 같은 마법사가 현재의 지위나 부의 추구를 위해 과거의 무언가를 바꾸는 행위 같은 것 말이지요."
rows["259:1097209708"]="여기 저는 아마도 세계에서 가장 위대한 유서 깊은 자료를 수집했습니다. 아웃랜드심지어 실버문 비교해 보면 시티가  ⁇ 다.$B$B제발... 보고 읽고, 마음껏 탐색해 보세요. 모든 것이 정리되어 있고, 명확하게 표시되어 있습니다."
rows["259:1108221475"]="오래전, 강렬한 유목동 사냥꾼 들 의 한 집단 은 세계 를 돌아다니고 있었다. 운명 이 우연 으로, 그들은 아제로스의 산더링 해가 대륙 을 갈라놓았을 때 판다리아 에 있었습니다. 유목동자들은 무겁고 위험한 땅인 타운롱 스텝 에서 갇혀 있었다."
rows["259:1227648837"]="강렬한 인간 마법을 북쪽 에 살고 있다고 한다. 그는 어떤 이유 를 모르게 그 땅 을 감시 하고 있다. 나는 직접 그곳 을 여행 하지 않았지만, 방문자 들 이 환영 받고, 심지어 그 에게서 일 을 하러 기꺼이 한다면 그 에게서 호의를 얻을 수 있다고 한다."
rows["259:132389597"]="독을 마셨나? 초기에 몇 滴만 마시게 해$B$B당신 은 심한 병 을 앓게 될 것 이다. 어쩌면 한두 개의 안테나 가 사라질 것 이다.$B$B하지만 충분히 오래 해보세요. 그리고 여러분은 익숙해 질 것입니다."
rows["259:1525736704"]="용맹한 용사들이여, 우리는 그대들에게 목숨과 자유를 빚졌습니다... 이 엄청난 은혜에 비하면 너무도 작은 보답이겠지만, 오늘부터 모두가 그대들의 업적과 이 어두운 성채의 그림자를 가르며 타오른 빛의 길을 알게 하겠다고 맹세합니다."
rows["259:1657130099"]="형제, 그것은 될 수 없다... (재명이 왔다!) 나의 힘... (너무 자랑스럽다! 그는 피를 말하고 있다! 들어!) 내 마음... (우리는 그의 영광을 위해 봉사한다!) 무슨 일이 일어나고 있다... (태양은 사라졌다. Twilight의 그림자가 온다."
rows["259:1920631442"]="다 양측에서 수집됐고, 이제 모든 것이 실리투스로 옮겨지고 있고 하루도 안 돼야 합니다. 그렇게 되면 누군가가  ⁇ 돌이 모래의 왕자리를 들고 스카라브 데이에 둥지를 울리면 전쟁이 시작됩니다!"
rows["259:1999901012"]="제국식물관에 오신 것을 환영합니다.$b$B오늘엔 스프라이트 감염이 별로 없어서$b$B사실, 당신이 여기 왔다고 아무에게도 말하지 말 수 있을까요? 특히 이 불쌍한 파야스코에 대해 말하지 말 수 있을까요."
rows["259:2144928581"]="누군가를 찾을 수 없는데?$B$B아니면 시장에 있고, 아니면 하루 동안 자기 집에 있거나, 아니면 Sunsong Ranch에 있는 겁니다.$B$B만약 그 곳들 중 어느 곳에서도 그들을 보지 못한다면, 눈 검사가 필요할지도 모릅니다!"
rows["259:313532951"]="저게 가난한 영혼들을 돌보는 일이야. 알도르나 스라이어 등 모든 사람들이 도움을 줄 수 있도록 도와줄 수 있어요.$B$B우린 너무 부족해서, 거북이를 어떻게 톱니케트를 써야 하는지 알았다면, 내가 돌리지 않을 거야. "
rows["259:400071779"]="용마오를 저주해!$B$B새들을 죽이고 가족들을 공격하고 땅을 빼앗고 우리 주변에서 세상이 무너지는 동안에도$B$B만약 당신의 얼라이언스이 와일드햄어의 도움을 원한다면, 우리를 이기기 위한 유일한 방법은,"
rows["259:50035629"]="새로운 식물 종에 대해 배우는 것은 우리의 탐험에 매우 중요합니다.$B$B식물 은 생명 의 여러 형태 가 존재 하기 위한 기초 를 마련 합니다. 그것 들 을 이해 하는 것 은 자연 전체 를 더 잘 이해 할 수 있게 해 줍니다."
rows["259:580635916"]="저 아래 안마당의 마나 폭탄을 조속한 시간 내에 실전에 투입할 수 있도록 준비하지 못하면 어떤 일이 일어날지는 말 안 해도 알지? 놈들이 숲으로 들어간 이후 여기 투렘과 남쪽의 해골이빨 폐허에서 진행 중인 우리 작전을 사사건건 방해하고 있다."
rows["259:947068917"]="이 모자 안 에 있는 인간형 인물의 희미 한 윤곽 을 보실 때, 여러분은 지금 이 위치 를 꼭 해야 한다는 것을 알 수 있습니다. 결국 이 모자를 열 수 있을 것 이라고 생각 하는 동안, 모자 를 열기 위해 가장 강력 하게 노력 할 때에도 불구하고, 그것은 단단히 닫혀 있다."
