rows["25:921812452"]="상어를 보려고?"
rows["25:922762248"]="다음 부대, 전진!"
rows["25:923989715"]="왜 뒤집어있어요?"
rows["25:9245617"]="어둠이 널 기다린다."
rows["25:931856241"]="모래 상자는 꽉 차 있어..."
rows["25:935338814"]="드디어 내 영혼이 자유로워졌어!"
rows["25:935376907"]="생선 손질하듯 네놈을 요리해 주마!"
rows["25:936377632"]="토로 때문에 걱정이 나네요"
rows["25:9435661"]="손잡고 있는 일방 거울!"
