rows["25:952636072"]="%s 당신의 길을 키스 해"
rows["25:953340266"]="항상 연설을 하고 있어요"
rows["25:954743299"]="발두란, 네 운명은 내 손에 있다!"
rows["25:955599565"]="작은 바퀴를 밀어내야 돼!"
rows["25:956866396"]="우리가 어떻게 해야 할까요?"
rows["25:957064035"]="누가 도와줄까요?"
rows["25:957181376"]="조심해, 게으른 무어들!"
rows["25:959462260"]="도와주세요! 저 짐승이 날 공격하고 있어요!"
rows["25:960245208"]="투어는 언제 시작될까요?"
rows["25:962063054"]="뭐, 뭐라도 원해?"
rows["25:9623638"]="그 일은 그냥 일어나지 않았어!"
rows["25:963020387"]="물고기는 목마른 적이 있나요?"
rows["25:964963119"]="이럴 수는 없다!"
rows["25:965693240"]="토템을 잊지 마세요!"
rows["25:967888502"]="도망쳐야 했어"
rows["25:968996003"]="우리 광산에서 나가!"
rows["25:974356935"]="테라모어한테서야!"
rows["25:975787129"]="리버송 장로가 어디 있어?"
rows["25:975855457"]="균형이 회복되어야 합니다!"
rows["25:977494356"]="아주 맛있어 보이는데..."
rows["25:978247484"]="난 순종하는 법을 가르쳐 줄 거야!"
rows["25:980218768"]="발가르데 항구로 데려다줘"
rows["25:980794322"]="죽어라, 서리 친구!"
rows["25:981899168"]="굴복해 빨리 해"
rows["25:986925468"]="%s는 네트워크에서 튀어나오게 됩니다."
rows["25:987077447"]="아, 얼마나 낭비가 되었는지... 다음!"
rows["25:987572975"]="이건 맛의 속삭임이야"
rows["25:989560480"]="베로그를 불러내! 위기에 처했다!"
rows["25:993007824"]="%s 안개가 사라지고..."
rows["25:996249408"]="당신 명령대로, 워치하이프!"
rows["25:997032887"]="할 일이 많이 있습니다."
rows["260:1273040097"]="메'린이  ⁇ 는 옷들을 보면, 엘우네가 자기 바늘을 축복했다고 생각할 수도 있습니다. 만약 네 바늘이 그렇게 축복되지 않는다면, 그녀를 방문해서 그녀의 가르침을 들어보는 것이 좋습니다. 다르나서스."
rows["260:1322792065"]="내 여동생은 아버지랑 농촌의 중간에서 살고 있습니다. 큰 크레인 동쪽$B$B가끔은 언니를 보고 싶지만 보통 다른 농부들이 이 곳을 지나갈 때까지 너무 바쁘게 보이는데"
rows["260:1492682946"]="당신은 큰 잠재력을 가지고 있지만 먼저 이해가 이루어져야 합니다. 영들을 받아들이고 그들의 부르심을 들어야 합니다. 그러면야 당신이 따라야 할 길을 준비할 것입니다."
rows["260:1534806043"]="|cff0000ff급 7:|r \010  GG 엔지니어링: $7411w-$7412w\010  암흑 소환자: $7413w-$7414w\010  배틀트론: $7375w-$7376w\010  육류: $7425w-$7426w\010|cff0000ff급 8:|r\010  헤크소스: $7871w-$7872w\010  타이슨 샌더스: $7873w-$7874w\010  T440 쌍방향 로봇: $8028w-$8027w\010  안트라사이트: $8030w-$8029w"
rows["260:1563236219"]="용감한 영웅들이여, 우리는 그대들에게 목숨을, 자유를 빚졌습니다... 이런 큰 빚을 갚기엔 너무나도 모자라겠지만, 그대들의 훌륭한 행동과 이 어두운 성채의 그림자를 가른 행보를 오늘부터 모든 이들에게 알리겠다고 맹세합니다."
rows["260:1620061688"]="|cff0000ff급 7:|r\010  GG 엔지니어링: $7475w-$7476w\010  암흑 소환자: $7477w-$7478w\010  배틀트론: $7439w-$7440w\010  육류: $7489w-$7490w\010|cff0000ff급 8:|r\010  헤크소스: $8064w-$8063w\010  타이슨 샌더스: $8066w-$8065w\010  T440 쌍방향 로봇: $8068w-$8067w\010  안트라사이트: $8070w-$8069w"
rows["260:1794631050"]="아, 병을 치료하는 사제보다 더 좋은 것은 없습니다. 물론 좋은 높은 술은 많은 병을 치료합니다. 하지만 브레엔나 플린트크래그가 맥주 만드는 법을 가르치지 않는다고 생각합니다."
rows["260:248267994"]="파멸의 인도자는 죽었고 앞으로 그런 인물은 절대 나오지 않을 것이오. 사령관, 당신은 그 아들 모그레인은 자기 아버지와는 전혀 다른 인물이라는 걸 알고 있었소! 붉은십자군 대영주 모그레인을 죽음으로 몰고 간 것은 결국, 당신이요!"
rows["260:332772346"]="잭의 남자들 앞에서 스턴트를 할 거야?$B$B그건 정말 많은 바보같은 걸 필요로 합니다. 그건 당신에게 비용이 들지 않을 겁니다. 저는 금보다 덜한 것에 대해 목숨을 걸지 않을 겁니다. 그리고 당신이 움직이기 전에 내가 길을 벗어날 때까지 기다려 주시면 좋을 겁니다."
rows["260:473967901"]="우리는 성전을 조사하고 있었는데 모그 군주와 그의 대원들이 도착했습니다.$B$B우리가 즉시 죽이지 않은 사람들은 포로로 잡혔습니다.$B$B내가 죽었을 때 여기 숨어있었어$B$B모가들이 왜 여기 온지 모르겠지만, 좋은 건 아닐 수 없어요!"
rows["260:683617828"]="볼진의 시신은 며칠 전에 우물에서 발견됐습니다.$b$b그의 혈관으로 독이 흐르고 있어 재생을 막고 있습니다.$b$b만약 추측해야 한다면, 이 상처는 암살자의 손으로 만들어졌다고 말할 겁니다."
rows["260:749841373"]="피부를 벗는 것 같으면 무릎만 벗을 수 있어 발투스 스톤플레이어한테 가서 어떻게 동물들을 제대로 벗겨야 하는지 가르쳐줘"
rows["260:932134494"]="코렌 디레브루는 미친 놈이야\010브루페스트에 출전하지 못했을 게 내 잘못이 아니야 하지만 그 일은 그와 그의 다크 아이언 동호들이 내 직원들을  ⁇ 고 내 맥주 전부를 마시기 싫지 않았어\010누가 이걸 끝내야지!"
rows["260:966514751"]="바로 그 순간! 그래서 주인은 두 번째 번으로 대두에 돌아왔지만 브란은 그런 말도 안되는 것을 하지 않았습니다!"
rows["261:1118881235"]="다 트라이라이라이트의 해머는 다 하이랜드에서 우리 반지를 공격하고 있습니다. 그리고 그들은 많은 것을 그들의 과정에 데모로 가져왔어요. 이것은 우리의 마지막이 될 것입니다."
rows["261:1615038271"]="동물의 피부를 사용하면 먹이를 먹거나 보호를 위해 떨어져야 합니다. 우리는 지구 어머니를 존중하고 동물에 대한 존중을 제공합니다. Chaw Stronghide는 이런 것들을 가르쳐 줄 수 있습니다. 당신은 그를 볼 것입니다."
rows["261:1652343614"]="그들은 거미들이고, 우리가 익숙한 거미들보다 좀 더 불꽃이 지향된 거미들이고$b$b물먹고, 밧줄을 굽고, 화려한 독을 뱉고, 내 친구들 중 몇몇을 화려한 실크 코코너로 잡습니다. 끔찍한 작은 것들."
rows["261:1845627535"]="네 명백한 약점에도 불구하고 난 너를 좋아해왔어, 웨이커. 전장에서 내 실력 때문에 모범이 되었다. 죽음 자체를 속일 수 있다고 말했어요."
rows["261:2107663097"]="안녕하세요, 저는 자연의 학생입니다.$B$B최근 나무 스프라이트 문제들을 조사하기 위해 보내졌어요$B$B저는 어린 시절에도 나무 스프라이트에 매료되어 왔습니다. 보통 폭력적이지 않습니다.$B$B장난스럽지만, 진짜 피해를 주는 경우는 거의 없습니다."
rows["261:446717273"]="이 기하급수자에서 암호를 구출하는 데 하루 종일 걸렸습니다.$b$b$b   푸른 눈빛으로 별빛이$b              밝혀졌어요$b$b   10개의 조각, 한 막대기, 그리고 베일$b             사라져버립니다.$b$b$b슈노츠와 그의 빈 약속을 잊어!$b$b이 수수께끼를 풀 수 있다면 그 비밀은 내 거야!"
rows["261:532256046"]="그 들 의 피 는 폭풍 으로 씻겨 져 백두대 호수 로 옮겨졌으며, 물 을 붉은 색 으로 변 시켰습니다. 마지막 숨으로 폭풍 은 호수의 중앙 에 타서, 그 물 자체 를 불태워 버렸습니다. 호수는 수흘 동안 적색 색채로 불었습니다."
rows["261:698316374"]="여기 광산 훈련자가 있나요?  \010왜 당신은 모든  ⁇  모로그에서 최고의 광부들을 찾을 수 있습니다. 대 동굴의 북쪽에 있는 깊은 산맥 광산과 보석 제조에."
rows["261:762024722"]="리치 왕에게 큰 타격을 주었군! 그대들은 은빛십자군의 강건한 용사임을 입증했네. 우리는 함께 얼음왕관 성채를 공격하고 남은 스컬지를 물리칠 걸세! 힘을 합친 우리가 이겨내지 못할 도전은 없네!"
rows["261:877480517"]="그가 발견되지 않는 한 내가 찾아보겠습니다. 그가 살아있다는 것을 알고 있습니다. 그리고 그를 찾아야 한다는 것을 알고 있습니다."
rows["262:1245871011"]="게임 토큰을 줘서 10개의 반지를 줄게 $B$B반지를 듀벤코에 던지세요? 그쪽의 암흑성거북이...$b$b만약 한번에 승리할 만큼의 링을 내리지 못한다면 다시 시도해 보세요."
rows["262:1319826582"]="누가 펄브로우를 죽였는지 말해줄게요. 왕 버라이언  ⁇ 은, 그 누구죠! 그리고 그는 우리 모두를 죽이고 있어요. 한 번에 한 개씩. 내가 말할 수 있는 유일한 것은 법이 도착하기 몇 시간 전에 몇몇 덩굴들이 이 곳을 떠나는 것을 봤다는 것입니다."
rows["262:1409947872"]="아담스 대장이 나를 하그린드에서 무슨 일이 일어나고 있는지 조사하러 보냈습니다. 하지만, 제가 이 곳에 접근할 수 있는 가장 가까운 곳이죠. 버려진 비클 타워는 호기심한 눈으로부터 약간의 보호를 제공해 줍니다.$B$B포세이큰은 저쪽에서 잘 안 돼"
rows["262:152575300"]="내가 계곡에 처음 왔을 때 당신에 대해 확신하지 못했지만 이제 자랑스럽게 이웃이라고 부를 수 있습니다. 제 우정을 표기하기 위해, 나는 당신의 농장에 큰 것을 줄 것입니다. 그녀는 이미 거기에 있어야 합니다. 이름은 미스 피피입니다. 그녀는  ⁇ 밥을 먹는 것을 좋아합니다!"
rows["262:1956718235"]=" ⁇ 터스킬드랑 얘기해  \010그리고 만약 내가 그의 애완 동물의 사업을 한 번 더 할 수 있다면, 그는 다른 사냥꾼들을 배후에 훈련시킬 것이라고 말해줘!"
rows["262:2017926545"]="이 지혜 는 위대한 썬더 블러프 에서만 발견 될 수 있는 신비 로  ⁇ 어 있다. 블러드하프 마을 에서 북쪽 으로 나가는 길 을 따라가며, 돌벽 아래 에 있는 엘리베이터 에 도착 할 때까지 그 위로 올라가서 블러프워치 의 한 사람 에게 추가 도움 을 요청 하십시오."
rows["262:2065867687"]="브릴에서 엔지니어링 트레이너가 없는데, 언더시티- 그 곳에 도착하기 위해 로데론 남쪽으로 내려가서 엘리베이터를 타고 언더시티 수호자 더 구체적인 방향에 대해"
rows["262:412958817"]="맞춤형이라고? 어머. 아, 물론요. 썬더 블러프북쪽에서 마을 밖으로 나가는 길을 따라, 블리프 밑에 도착하면 엘리베이터를 타고 승강장 꼭대기에 올라 블리프워치 중 한 명과 이야기해 보세요."
rows["262:460321471"]="금 로토스는 영원한 꽃의 계곡을 방어하는 역할을 합니다.$B$B만약 당신이 우리를 돕고 싶다면 골든 로터스의 적들을 물리치고$B$B또한 아인지 오터라이트와 함께 더 많은 작업에 대해 이야기 할 수 있습니다."
rows["262:494955146"]="내 형 크리엑스는 오그리마에서 일하는 것을 나쁘다고 생각한다. 이 곳의 냄새와 비교할 수 있는 것은 아무것도 없습니다. 적어도 보스가 나에게 위험 대가를 지불하는 품성을 가지고 있었다!\010제펠린이 어디 있는지 보고 싶니?"
rows["262:511151390"]="사실 말'가니스는 십자군 광장에서 스컬지를 지휘하고 있지만, 도시 입구에서 그곳으로 가는 문은 닫혀 있습니다.$B$B작은 군대가 도청을 통과해서 광장을 갈 수 있다는 걸 모르는 거요"
rows["262:582769288"]="엄마는 오렌지 좋아하지만 골짜기에서 오렌지는 찾아보기 힘들어요$B$B내가 내 아들을 시장에서 오렌지 좀 사라고 했으니 구리 좀 줘$B$B뭐하는 거야?$B$B우린 농부 아냐, 야크 목회자야! 멍청한 콩은 뭐해?"
rows["262:656082544"]="난 너처럼 흑사 용 비행기가 뉴 카가트에 대한 의지를 주장하는 것을 발견하게 놀랐어$b$b그럼에도 불구하고, 고위 검사 혈액 감시자는 내가 멀리서 지켜보고, 모든 것이... 못생긴하지 않도록 부탁했습니다."
rows["263:132494627"]="에테레럴 테크노마커의 세 명이 스톰윈드에서 캐서더럴 광장 남쪽의 운하를 따라 가게를 설립했습니다.\010\"삼풍\"이라고 부르죠. 이상한 기계와 보라색 빛을 찾아보세요.\010그들이 원하는 서비스를 제공합니다."
rows["263:1432323155"]="용기 있는 기미들이 곤메리건에 진입한 기술로 저는 가장 위대한 발명품을 만들 수 있었습니다. 물질 운송수단!"
rows["263:1717247102"]="많은? 두 가지 약점이 있습니다. 서쪽의 구조의 기초와 동쪽의 구조의 기초. 잠깐만요. 어떻게 벡터 코일에 대해 아무것도 알 수 있을까요?"
rows["263:1924147342"]="내가 이 모든 걸 기억해야 한다고 생각하니? 이럴 만큼 돈을 내지 못했고 계약은 내 침묵만을 요구했지. 그래서 내가 이 책들을 바닥에 놓아놓고$b$b- 알았어?"
rows["263:21105714"]="존니 어저블이 도착했어요. 필리스티네, 당신의 소수적인 업무를 내게 보여줘서 제가 완만하게 열정을 가지고 수행할 수 있도록 해주세요. 그리고 아마도 지도가 보여주는 것보다 더 복잡한 방향을 전혀 무시할 수 있을 겁니다."
rows["263:2114411833"]="감염된 작물은 곤충으로 덮여 있습니다.$B$B하지만 이제 이 파동파 발사기가 있는 상태라면, 그것들을 제거하는 것이 쉬울 것 같습니다. 그것을 돌려서 모든 해충들을 살균제 없이 인간적인 방법으로 제거할 수 있습니다.$B$B우리 채소는 유기농으로 간주되는가?"
rows["263:69320125"]="이렇게 작은 지역에만 많은 죽음과 절망이 있을 수 있다는 것은 상상하기 어렵다. 하지만 진흙 뒤에는 혼란과 파괴가 몰려드는 땅이 있습니다.$B$B발걸음을 조심해, 모험가."
rows["263:83535737"]="저는 한때 전쟁에서 벗어나 고향의 문제를 해결하기 위해 서부 몰락지대- 그건 평생 전에 그랬던 것 같네요 빛 이 데피아즈단 더 이상 위협이 되지 않습니다.$B$B우린 고향에서 멀리 떨어져 있지만 이 전투에서 승리하지 못하면 다시 돌아갈 수 있는 서부 몰락지대가 없을 수도 있습니다."
rows["263:844387276"]="그 거대한 흙 덩굴들이 덩굴 아래로 움직이는 것을 본 적 있나요? 그들은 터널 벌레의 종에 속해 있습니다. 그 종류는 아제로스는 본 적이 없습니다! 나는 자신 같은 경험이 풍부한 모험가에게는 그 어떤 것도 싸우는 것이 훌륭한 학습 경험일 것이라고 확신합니다."
rows["264:1207129892"]="이건 전문적인 장비야 조심하지 말고 너무 많이 롬을 먹었으면 안 써$B$B그 얘긴 할 때... 그런 거칠게 있는 건 없잖아?"
rows["264:133768463"]="탐험 지점은 배치하기 어려운 곳이지만 명예 포지션의 방어에 매우 중요합니다. 여기 수집된 정보와 우리 군인들이 레지온과 지트 고르의 오크에 맞서 싸우는 전투는 얼라이언스의 지옥불 캠페인에 귀중합니다."
rows["264:1519049830"]="아니, 캡틴, 트랭킬린의 또 다른 서명된 편지가 도착했습니다. 대행사 마브렌이 다시 서명했습니다. 왜 우리가 전에 명령한 것처럼"
rows["264:1526070438"]="이런 곳에서 다른 모험가들도 있다는 것은 놀라워요!$B$B만약 이 홀들에 대한 연구 이론이 옳다면,"
rows["264:1626264614"]="이 구멍은 냄새가 나고 뱀들이 날 둘러싸고 있지만, 난 일하러 왔어.$b$b푸트레스가 화성문에서 스턴트를 한 이후로, 장군은 이 사람들을 버리는 만큼 신뢰하지 않습니다. 그래서 우리는 여기 있습니다. 약사들은 나 없이는 아무것도 할 수 없습니다."
rows["264:1942216890"]="저는 솔즈베리에게 그를 괴로스로 바꿀 수 있는 방법이 없다고 반복해서 설명하려고 노력했습니다. 그는 듣기를 거부하고, 대신 자신은 자신에게 자신은 자신은 자신은 자신은 자신은 자신은 자신은 자신은 자신은 자신은 자신은 자신은 자신은 자신은 자신은 자신은 자신은 자신은 자신은 자신은 자신은 자신은 자신은 자신은 자신은 자신은 자신은 자신은 자신은 자신은 자신은 자신은 자신은 자신은 자신은 자신은 자신은 자신은 자신은 자신은 자신은 자신은 자신은 자신은 자신은 자신은 자신은 자신은 자신은 자신은 자신은 자신은 자신은 자신은 자신은 자신은 자신은 자신은 자신은 자신은 자신은 자신은 자신은 자신은 자신은 자신은 자신은 자신은 자신은 자신은 자신은 자신은 자신은 자신은 자신은 자신은 자신은 자신은 자신은 자신은 자신은 자신은 자신은 자신은 자신은 자신은 자신은 자신은 자신은 자신은 자신은 자신은 자신은 자신은 자신은 자신은 자신은 자신은 자신은 자신은 자신은 자신은 자신은 자신은 자신은 자신은 자신은$B$B거미들은 매우 이상한 존재다."
rows["264:337491869"]="그럴지도 모르지. 하지만, 이건 알아두게. 리치 왕은 언제나 존재해야만 해. 그대가 아서스를 물리쳐도, 누군가가 그의 자리를 대신해야만 하네. 리치 왕이 지배하지 않으면, 스컬지는 굶주린 메뚜기 떼처럼 이 세상을 휩쓸며 모든 것을 파괴할 테니까."
rows["264:650389699"]="펠 크리스탈 포크를 사용하여 당신의  ⁇ 은  ⁇ 은  ⁇ 을 동물의 불안정한  ⁇ 으로 변형시킬 수 있습니다. 이  ⁇ 은  ⁇ 을 더 민첩하고 강하고 더 심하게 만듭니다.$B$B하지만, 한 병이라도 구매할 수 있는 10개의 조각도 없는 것 같습니다."
rows["265:1447844075"]="리치 왕은 아제로스의 각 수도 도시들에 대한 작은 세력을 가져왔으며, 그들의 주요 세력은 주기적으로 다음 땅을 공격했습니다.$B$B아즈하라, 불어난 땅, 타는 스텝, 타나리스 사막, 동부 전염병 땅, 겨울 봄"
rows["265:1686671327"]="브릴에 은행이 없어서 언더시티 그 때문에 로데론 남쪽에는 엘리베이터가 있습니다. 언더시티- 거기 있으면, 언더시티 더 정확한 방향에 대한 경호자"
rows["265:1705281627"]="네 일은 괜찮지만 학생에서 내가 찾는 품질은 별로 없다 골드샤이어난 그가 몇 가지 기본을 가르쳐 줄 수 있을거라고 확신하고, 그리고 당신이 끝낼 때, 내게로 돌아가서"
rows["265:17856200"]="얼음 늑대 영토로 들어가지 말고 군인, 이 망할 곳이 모두 폭탄에 갇혀 있어"
rows["265:339880205"]="보시, 자네에게 큰 부탁이 있어, 네 머리를 잘라내야 해\010부티베이에서 널 필요로 해 보시 지금 그 어느 때보다\010"
rows["265:393252059"]="잠깐 쉬세요, 감독님, 루안 웰드에 재임한 이후로 자주 볼 수 없어요$B$B내가 제안하는 것을 보세요. 우리가 마지막으로 얘기한 이후로 큰 변화가 없었을 수도 있지만,$B$B그리고 너무 낯선 사람이 되지 마!"
rows["265:514361765"]="오크를 돌릴 수도 있고 트롤을 잘라낼 수도 있고, 오그르의 날개에 자발자자를 조각할 수도 있지만 동물의 피부를 벗겨내지 못해요  \010만약 당신이 그것을 할 용기가 있다면, 구시가지의 보호소에서 마리스 그레이저를 찾아보세요."
rows["265:703339794"]="아졸네룹의 고위 거미 군주인 아눕레칸은 원래 아눕아락의 휘하에 있었으나, 리치 왕에게 패한 이후로 스컬지의 휘하에 들어갔다. 옛날에는 아눕아락 휘하의 지휘관 중에서도 가장 충성스러웠다고 하더군."
rows["265:70755918"]="상처뿐인 승리로군. 오늘 받은 손해로 우리 전력은 약해졌네. 이런 어리석은 짓으로 리치 왕 말고 또 누가 이득을 보겠나? 위대한 용사들이 목숨을 잃었네. 무엇을 위해서였나? 진짜 위협은 저 앞에 있네. 리치 왕이 우리 모두를 죽음 안에서 기다린다네."
rows["265:750035833"]="제디스 바로프의 일기에는 죽은 자들에 대한 거론과 험담이 가득합니다. 책의 마지막에 어떤 종류의 가방의 제작을 위한  ⁇ 질 패턴이 보입니다.  ⁇ 질에 대한 이해는 패턴을 해독하기에 충분하지 않습니다."
rows["265:800653383"]="상상력은 한계가 친구, 당신이 그것을 어떻게 만들 수 있는지 알아낼 수 있다면 당신은 그것을 만들고 상자하고 전세계의 소매업체에 배송 할 수 있습니다. 물론, 당신은 마케팅을 처리해야합니다."
rows["265:846974265"]="고대 하카르 제단이 방 입구 근처에서 조용히 서 있습니다.$B$B그 위에 있는 발코니들을 보면 뱀 모양의 큰 동상이 각 위에 서 있는 것을 알 수 있습니다. 동상은 여러분 앞에 있는 제단과 매우 비슷합니다."
rows["265:962101858"]="이 모든 것들은 양측에서 수집됐습니다. 이제 모든 것이 실리투스로 옮겨지고 있고, $2113w일 이내에 그곳에 도착해야 합니다. 그렇게 되면, 누군가가 횡단 모래의 왕자리와 함께 스카라브 데이에  ⁇ 을 울리면, 전쟁이 시작됩니다!"
rows["266:1080631315"]="제 동료들이 어둠을 막는 경계선을 지키고 있는 동안, 저는 마법으로 위대한 어둠의 바깥으로 도달했습니다. 그곳에서 저는 엄청난 빛의 존재들을 감지했습니다.$B$B아달과 나루가 발견됐어요"
rows["266:1166444621"]="얼라이언스와 호드 군대가 연합하여 분노의 관문을 공격하자마자, 언더시티에서 반란이 일어났다. 바리마트라스와 그의 악마 종자들이 공격한 것이었지. 수많은 백성이 불시에 살해당했고 나도 간신히 도망쳤다."
rows["266:1169725114"]="드래곤마우는 부패한 사람들이다. 그들은 이 섬의 모든 자연 자원을 채취하고 그 자원을 이용해 일리던의 군대를 블랙 테플에서 공급하고 있습니다. 그러나 그들은 많은 것을 스스로 가지고 있으며, 그들이 숨긴 모든 것을 가장 높은 입찰자에게 판매합니다."
rows["266:1297030634"]="아타스는 스트라톨메의 곡물 피해를 알고 있고, 목살을 시작할 예정입니다.$B$B하지만 아직 뭔가 잘못됐어요. 이 시간줄에 외계인이 존재한다는 것을 감지하고 있습니다."
rows["266:1330167189"]="안전하지 않은 곳이고, 초기 연구자들은 아직 탐험에서 돌아온 적이 없습니다.$B$B다시 묻습니다. 확신하십니까?"
rows["266:1553670823"]="요리품 전면에서는 우리가 수집하고 보관하는 것을 성공한 것으로 보입니다 $2092w 무지개 날개 알바코어 $2093w 또한, 현재 우리는 $2098w 이 중 $2099w 굽은 랩토르 및 $2101w 이 중 $2103w 냉장고에 얼룩진 노란색 꼬리"
rows["266:1585957714"]="그래프론을 타는 욕심이 없어서 다행이군 다리를 바닥에 얹을 수 있는 대안이 있어"
rows["266:187413252"]="신조들은 드루이드들을 감시하고 있는 것 같군!$B$B와일드하트 포인트를 볼 수 있는 윙글 포털사이트를 통해$B$B여기서 일을 끝낼 때, 이 방법은 빨리 빠져나갈 수 있는 좋은 방법일 겁니다."
rows["266:1997696067"]="낯선 사람, 만약 당신이 당신의 도움이 필요한 곳을 찾고 있다면, 당신은 그것을 찾았어.$B$B죽은 사람 들 이 다시 깨어 나고, 육지를 걷고, 대양 을 건너온 배 들 로 도착 합니다. 피오르드는 우리 에게도 너무 위험 해지고, 곧 우리 는 북쪽 으로 더 안전한 땅 으로 떠나야 합니다."
rows["266:2032772072"]="이 곳의 땅은 아직 피가 흘려온 곳입니다. 오, 악마들이 그 포털을 뚫고 아제로스의 영웅들과 충돌했을 때, 저는 이 곳에 있는 것을 내 눈으로 보고 있었으면 좋겠습니다!$B$B하지만 이제, 그 반대편에서 더 치열한 전투가 격렬해지고 있습니다!"
rows["266:2112315798"]="네파리안, 죽음의 날개의 종은 이제 스파이어를 통치하고 있습니다.$B$B만약 당신이 어떻게든 상승의 홀을 통과할 수 있다면.$B$B<이트리그가 숨쉬고 있다>$B$B불행히도, 흑 비행에 의해 가치가 있다고 인정되는 사람들만이 승천의 특권을 얻습니다.\010"
rows["266:254028760"]="칼은 결코 너무 날카로운 것도 아니고 장갑도 너무 단단한 것도 아니기 때문에 재능 있는 마법사가 항상 필요할 것이다. 그런 마법사는 타라단입니다. 그는 무기와 장갑을 개선하기 위해 마법을 제대로 짜는 방법을 알려줄 수 있습니다."
rows["266:283445219"]="맞아요. 여러분들이 들어보셨을 겁니다. 이 미노우는 제가 만든 끔찍한 생물입니다. 제가 휴식을 취하고 있을 때 이 미노우는 무운 어부들을 떠올리는 것을 좋아합니다.$B$B아저레고스 웃음"
rows["266:608387410"]="우핑 (Weller's Arsenal) 의 인간 무기 마스터로부터 스톰윈드, 한디어, 트레이더의 계층에서 발견된 드레네이 무기 마스터 또는 Bixi Wobblebonk, Timberline Arms 내 gnome 무기 마스터 아이언포지."
rows["266:735721874"]="당신은 지구의 어머니 뼈를 호드 ⁇ 스피 마을에서 북쪽으로 가는 길을 따라 썬더 블러프- 블러프워치는 더 많은 도움을 줄 수 있습니다."
rows["266:848979978"]="제 영혼을 희생하려고 하는 거야$B$B발고르가 떨고 있습니다.$B$B내 식습관에 대해 두 번 생각해봐$B$B 어쨌든, 내 움직임을 지켜보는 경비자가 있어 나 혼자 이리 나가지만 좋은 방해가 필요해"
rows["266:891664782"]="지금 당장 죽여야 할 때, 무거운 폭탄은 갈 길이에요. 무거운 폭탄은 훨씬 더 큰 반경을 가지고 있고 훨씬 더 많은 피해를 입게 됩니다. 단점은 여러분이 폭탄을 발사할 수 있는 것보다 훨씬 적은 무거운 폭탄을 들고 다니는다는 것입니다. 그리고 사용 사이에는 더 오래 기다려야 합니다.\010"
rows["267:1035363175"]="예, 하지만 저는 이 곳을 진짜 이름으로 알고 있습니다. 엘드레 타라스. 그것은 수 년 전 밤 엘프들에게 마력이 있는 요새였습니다.$B$B엘드레 타라스, 젊은 사람, 지금 내 처지에 있는 것과는 일치한다고 해도 과언이 아닙니다."
rows["267:1036478548"]="아, 황금화 장미... 그 부드러운 침대가 있고 따뜻한 목욕탕이... 그 숙소를 생각하면..."
rows["267:1075039204"]="이제 시간이 왔습니다 호드 그리고 얼라이언스 이 방향으로 노스렌드 그리고 리치 왕최근 몇일 동안 칼림도어 동부 왕국들이 공격당하고 있습니다."
rows["267:1084728988"]="고엘은 살아있는 돌이 됐어 디폴름의 동굴 안에 쫓아 가야 돼$b$b지구 반지가 그녀의 왕국을 구한 것을 보고 테레잔은 그를 구하는데 도움이 될 것 이상으로 기꺼이 할 것입니다. 그렇지 않으면, 돌모아는 내게 책임을 질 것입니다!"
rows["267:1166976451"]="만약 내가 발사구역에 도착해 줄 수 있다면, 그 아름다운 공중 기계를 하나만 줘서,$B$B또 다른 낙하산이 필요하다면, 우리는 떨어뜨리는 지점 근처에 있는 상자 안에 몇 개를 보관해 두었습니다."
rows["267:1436033226"]="변명도 원하지 않고 결과를 요구합니다!$B$B우리가 지금 하는 일은 농담이라고 생각하십니까? 우리가 제대로 하지 않는다면,$B$B그게 원하는 거야?"
rows["267:1912210281"]="몇 년 동안 고품질의 양육 기술 과 많은 보살핌 을 받은 후 이 말 들 을 여러분 에게 보여 주기 를 영광스럽게 생각합니다. 여러분 이 말 들 을 산책 에 위해 고려 하는 것 처럼 시간 을 좀 사용 하십시오. 말 은 영원 히 동반자 입니다. 친구 여러분, 자기 를 사물 하지 마십시오. 오늘 이 자리에 올리고 말아요!"
rows["267:239274746"]="날 만나기 위해 무릎을 꿇었지?$b$b이 세상에서 내가 차지하는 위치를 알고 있고, 더 강하고, 혼자 싸울 만큼 강한 사람이 아니기 때문에 반려동물을 키우고 있습니다.$b$b그들이 널 보지 못하기 전에 날 멀리 떨어져 있어야 돼"
rows["267:291757881"]="<그림의 머리 속의 흐름을 흐리게 하고 그 주변을 들여다보게 됩니다.>$B$B만약 여러분이 파라홀론 평야를 보았다면, 이 곳이 같은 곳이라고 믿지 않았을 것입니다. 불과 몇 달 전만 해도 서부 몰락지대에서는 이 들들이 부적절한 모습을 보이지 않았을 것입니다.$B$B이제 그 모든 것이 사라졌지만 어떻게 그리고 왜?"
rows["267:347569652"]="오, 오, 웃기지 마! 난 유일한 버드 네드렉이야!$b$b이 땅을 다 여행해 왔어요. 하이달 산에서 잠든 성전까지요. 사실, 내가 제일 먼저 잠든 성전이라고 불렀어요.$b$b그래, 내가 그랬어.\010"
rows["267:510027402"]="많은 전투를 보았고 많은 동맹을 치유했고 많은 영혼을 깨끗하게 했습니다. 그리고 많은 적들이 제 지휘의 희생자가 되었습니다.\010당신은 도시의 벽 안에서 안전하다고 느낄 수 있지만, 실수를 하지 마세요. 전쟁은 이 땅을 전염병처럼 괴롭히고"
rows["267:665139099"]="현재까지는 그렇다. 하지만, 계속 분발하기 바란다. 캘타스 왕자님께서는 무너진 하늘 마루에서 수정 실험이 실패한 것에 대해 실망하셨다. 그래서 세나리온의 드루이드들을 대상으로 폭탄을 실험하는 것이다."
rows["267:698480474"]="순수한 샘플은 의도하지 않은 영향에 의해 손상되지 않은 것입니다. 우리는 가장 기본적인, 정상적인 환경에서 생물들을 찾아야 합니다.$B$B문명이나 아제로스의 지배적인 인종의 영향이 없는 곳이란 뜻이죠."
rows["267:855252401"]=" ⁇  잭, 우리는 아안키라지에서 곤충들과의 싸움에 직면해 있고, 우리는 그것에 대비해야 합니다. 저는 여기 철줄을 수집하고 있습니다. 현재 얼라이언스에는 $2002w 철줄이만 있지만, 우리는 전쟁에 총 $2003w을 필요로 할 것으로 예상됩니다."
rows["267:882816869"]=" ⁇ ,  ⁇ , 똥... 여기서는 그런거만 들어요!$b$b여기, 여기. 애완동물이 있잖아? 네, 물론 있어. 당연히. 작은 애완동물. 나는 그들을 위해 혼합물을 가지고 있습니다. 그것은 그들이 똑똑하고 강한 생물, 예. 예. 강합니다.$b$b시도해봐!"
rows["268:1158159399"]="대회 상원의원은 코리 ?? 이 끝난 지금 대회를 운영하는 짐을 일부 부담하도록 요청했습니다. 챔피언으로서의 권리를 얻은 자들과 우리 눈앞에 자신을 증명한 자들도 이 과제에서 도움을 요청합니다."
rows["268:1173805419"]="프록이라는 오래된 친구가 가젯잔으로 향하고 있었으나, 그는 배의 승무원들과 함께 도착하지 못했습니다."
rows["268:1190160280"]="'의 힘' 칼림도어 퀴라지 군대의 마지막이 패배하고, 아안키라지의 고대 도시 요새로 물러나고 있습니다. 칼림도어 그들은 나타나자마자 사라지고 흙을 찢어 버린 것 외에는 아무것도 남지 않는다"
rows["268:1722026387"]="우리는 오랫동안 지구 경호자와 그의 자녀들을 구출할 수 있기를 바랬지만 어느 순간에는 이 용들이 세상에 내리는 파괴를 해소할 수 있는 구출의 양이 없다는 것을 깨닫는 지혜가 있어야 합니다.$B$B어느 순간 우리는 개입해야 합니다."
rows["268:1742873827"]="그들은 광산 훈련자를 가지고 있다고 들었습니다 언더시티남쪽으로 나가서 헐리우드의 뒷면에 가야만 하면 로데론엘리베이터를 타고 언더시티 스스로에게 물어 언더시티 수호자 더 많은 방향에 대해"
rows["268:2056986883"]="|TInterface\\Icons\\spell_shadow_psychicscream.blp:20|t황제 비지르 조로크는 당신을 공격했습니다 |cFFFF0000|Hspell:122761|h[출력]|h|r 생존 능력을 사용하거나, 생존 능력이 높은 동맹을 갖고 서라!"
rows["268:2058823668"]="보통 우리는 초의 요구를 충족시킬 수 있을 것 이상이야$B$B<만은 잠시 동안 머리를 긁어보고 생각하게 된다.>$B$B다른 혈관을 통해 흘러가는 것 처럼 $B$B내가 시인이 아니야$B$B문제는 우리가 문제가 있다는 겁니다."
rows["268:2129293936"]="소문이 권력자들에 대한 연결성을 가지고 있습니다. 사실, 최근에 보르바르 신부에게 대해 특히 불쾌한 이야기를 들었습니다.$b$b다른 곳에 거짓말을 퍼뜨려서, 자신의 잘못을 고백할 준비가 되자 빛."
rows["268:233788101"]="마치 영원처럼 느껴진 후, 빈디케이터는 의식을 잃었습니다. 고문도 그에게 너무 많았습니다. 잔인한 사람이 - 마티스라는 이름이 알고 있었기에 - 그의 황폐된 몸으로 전염병과 연쇄된 물을 뿌리면서 사라우안을 깨우려고 시도했습니다. 하지만 사라우안은 깨어나지 않았습니다.\010"
rows["268:325891402"]="전 도전을 제안하는 모든 사람에게 도전을 받아서 즐거웠지만, 저는 그렇게 쉬운 승리에 지쳤어요.$B$B지금은, 제 반응기 사업을 시작해서 Twilight's Hammer에 대한 경험을 담은 책을 쓰려고 시간을 쏟고 있습니다."
rows["268:435633941"]="제플린의 뒷부분에서 떨어지고 프로펠러를 치고 돌에 착륙한 후 머리가 돌고 단단하게 만들기 위해 금속 그릇을 붙여서$B$B<그는 자신의 두개골에 자신의 손길을  ⁇ 습니다.>$B$B그 다음에는 번개가 일어납니다."
rows["268:573259774"]="오래된 스팀 탱크를 찾고 있나요?$b$b네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네.$b$b보통은 2개의 토큰이 필요하지만 군 복무로 인해 1개의 토큰을 할인율로 받을 수 있습니다.$b$b우린 다크문 페어에서 봉사해주셔서 감사합니다."
rows["268:910779695"]="몇 년 전, 나는 풍자 라이더를 연구하려고 함에 갇혔지만, 자유를 얻었을 때, 나는 돌아와 그들을 보호하기로 결심했습니다.$B$B이제 대폭발이 발생하고, Twilight's Hammer는 이 모든 신성한 생물들을 포획하고, 더 나쁜 것은 그들을 파괴하고 있습니다."
rows["269:1014515451"]="고엘, 당신이 트랄이라고 부르는 그 영혼은 원자계위에 흩어져 있습니다.$b$bTwilight의 해머는 우리의 의지를 흔들려도... 하지만 우리는 약화되지 않을 것입니다. 우리는 고엘을 포기하지 않을 것입니다.$b$b이 세상을 구하기 위해 모든 것을 위험에 빠뜨렸어요. 그리고 우리는 그보다 덜 할 수 없습니다!"
rows["269:1322156646"]="기다리게. 제단에 뭔가 새겨져 있군. 이건 경고일세. \"이 검을 집는 자는 무한한 힘을 얻게 될 것이다. 그러나 검이 육신을 베듯이, 이 힘은 영혼에 상처를 남기리라...\" 아아, 왜 몰랐을까! 이 검은 저주받았네! 어서 여기서 나가세!"
rows["269:1505026330"]="넌 잘생긴 놈이야 남해안을 방어하는데 도움이 필요해$B$B저 망할 포세이큰들은 모두 해로우의 끝이기 때문에 분노하고 있습니다. 그들의 \"축제는\" 의심의 여지없이 그들을 바로 우리 문 문으로 이끌 것입니다."
rows["269:1648000517"]="베르텔름이 그의 최신 창작을 위해 털을 수집하고 있다고 들었어요$B$B아니, 그건 그가 늑대 털 모자를 비밀로 지키기 위해 쓰는 커버 뿐이야. 그는 전투에서 흙을 닦기 위해서만 털을 수집하는데 그 모든 노력을 기울이지 않을거야!"
rows["269:1987661841"]="이 샘플을 보세요. 이 샘플은 무엇을 의미할까요? 이 샘플은 무엇을 의미할까요? 이 모든 정보를 살펴볼 시간이 필요해요. 그리고 더 많은 정보를 필요로 합니다.$B$B뭐 할 거야?$B$B해결책이 있어야 합니다!"
rows["269:628449535"]="여기 어딘가에 그 숫자가 있었거든요. 아, 예, 여기 있네요! 얼라이언스 수집한 $2047w  ⁇ 어먹는 $2048w 필요하다고 합니다. $2053w 이 중 $2055w 보라색 롯데와 $2057w 이 중 $2058w 아스타스의 눈물이 필요했습니다."
rows["269:67062989"]="우린 잡았어!$b$b비참한 얼라이언스 배들... 우리는 스톰윈드로 길을 갈라서 그들을 끝낼 수 있었다!$b$b...그러나 갑자기 거대한 기둥이 우리 배를 잡아...$b$b생존자들은 물에 닿자마자 나가에게 잡혔습니다."
rows["269:794724562"]="이 애쉬브링거였어 스컬지 모그라인의 칼이 빛나는 것처럼, 젊은 모그라인은 탈출을 위한 신호로 받아들였죠."
rows["269:858771031"]="내가 직접 봤어, 가장 큰 마쿠라가 산 거리의 손목보다 크며, 그 쌍둥이 거대한 한의 옆구리에 걸려갔어요."
rows["269:938876554"]="늦은 시간, 지연, 그리고 더 많은 지연. 십자군 재판은 현재 Wilfred Fizzlebang의 행동에 대한 조사 결과를 기다리고 있습니다. 다음 주에 재판이 계속됩니다."
