rows["270:1605652583"]="어떤 물건의 모습에 만족하지 않나요?$B$B트랜스모그리피터, 가장 강력한 기술자동차 중 하나인데 그 기기로 숙련된 워프 웨이버는 한 물체의 외관을 다른 물체로 바꿀 수 있습니다.$B$B이 겸손한 사람이 당신에게 어떤 영향을 줄 수 있을까요?"
rows["270:1661135128"]="내 겸손한 계곡에 오신 것을 환영합니다. 당신의 맛의  ⁇ 이 경험했던 다른 모든 경험을 겸손하게 할 정도로 맛있는 음료를 만드는 것이 내 인생의 목표입니다.$b$b제 연구는 어떤 현상적의 임박에 있습니다. 어느 판다렌도 이룰 수 있는 것이 아니라고 주장할 수 없습니다."
rows["270:1897410662"]="생각해보세요. 이 장소는 우리 시간 흐름과 존재 자체를 벗어나 수천 년 동안 있습니다.\010우리 경험 많은 웨이버들은 섬의 시간적 위치가 현재 안정된다고 확신합니다.\010우리가 그 위에 있을 때 다시 사라진다면?"
rows["270:1906588536"]="Pele'keiki 알다시피, 그것은 그에게도 불가능한 것처럼 보이지만 우리는 모든 불꽃을 가지고 있습니다 호드 만약 당신이 너무 게으른다고 느끼지 않는다면, 페레키키는 당신이 다른 사람들을 도와줄 것이라고 생각하죠."
rows["270:2047989327"]="우리가 우리 가장 신성한 황제처럼 살 수 있었으면 좋겠다. 우리의 모든 짐을 한쪽으로 내려놓고 우주와 조화롭게 존재할 수 있었으면 좋겠습니다."
rows["270:307374466"]="스톰파이크 정보통신사에서 윈터엑스 트롤들이 괴물 엔지니어들을 포로로 잡았다고 보고했습니다."
rows["270:332997915"]="안 돼! 뭔가 무서운 일이 벌어졌어요! 무한의 용군단이 제 동료 하나를 사로잡아 끔찍한 짓을 하려고 해요!$B$B아서스와 함께하는 게 당신이 해야 할 가장 중요한 일이지만, 재빠르게 행동할 수 있다면 시간의 수호자도 구할 수 있어요!"
rows["270:464827565"]="모든 사람들의 노력 덕분에 이제 필요한 철줄이 다 있어요 다른 한 명에게 물어봐요. 전쟁에 필요한 다른 물건이 있는지 확인해 보세요."
rows["270:743301987"]="마법으로서, 당신은 이 곳으로 다시 데려갈 포털을 불러올 수 있는 선택된 집단의 한 명입니다.$B$B그리고 기억하세요, 항상 내 뒤에 있는 크리스탈을 이용해 크리스탈송 숲의 다라란 아래의 유적으로 이동할 수 있습니다."
rows["271:1049556280"]="부활의 배는 에ಲಿ멘티움으로 강화되어야 합니다. 이 미네랄의 원천은 하나밖에 없습니다.$B$B지구형인 한 사람이 있는데, 저보다 더 많은 것을 알고 있는 사람이야"
rows["271:1094895913"]="이 작품 을 얻는 확률 은 백만 명 에 한 번 이 될 것 이다! 한 번 한 번 한 피부! 이 작품 의 가장 정통 한 공예 가라도 순수한 샘플 을 발견 하기 전 에 그 짐승 을 벗기기기 과정 에서 수백 번 이 실패 할 것 이다.\010"
rows["271:1110318795"]="언더시티 안에 박쥐 관리자가 있다. 브릴에서 내려오는 도로에서 남쪽으로 이동하고, T 교차점에서 서쪽으로 이동한다. 로데론의 유적은 왼쪽에 있을 것이다. 그 안에 들어가서 언더시티로 내려갈 수 있다. 당신은 더 많은 도움을 요청할 수 있다 언더시티 수호자"
rows["271:1142682299"]="몇몇 상은 십자군이라는 칭호를 얻은 사람들에게만 적합합니다. 아르헨티나 십자군과 그들의 동맹국들 모두에게 높이 평가받습니다.$B$B티리온은 저한테 그런 영웅들을 찾아서 적절한 훈장을 주겠다고 했습니다."
rows["271:129223583"]="타르시스의 눈은 빛나는 것 같아요$B$B한 번은 키린 토르의 경고에도 불구하고 그것을 붙잡았어요. 필사적이었죠. 무한한 힘이었습니다. 내가 원하는 대로 하고 싶은 힘을 가졌어요. 그리고 그만큼 빨리, 그것은 내게 빼앗겼습니다.  "
rows["271:1312502591"]="물론 모든 것이 불꽃을 피우고 거대한 헬륨 폭탄처럼 폭발하는 위험은 없습니다. 이 아기가 당신을 언더시티 어떤 배 보다 더 빠르고 안전 한 곳 이 되고, 그 시야 는 정말 참신한 곳 이다."
rows["271:1444627730"]="내 친구, 내가 스스로 당한 상처, 내가 리치 왕의 손에 너무 많은 공포를 저지른 세상을 바라볼 수 없었어요.$B$B그것은 나의 첫 번째 해제 단계이고, 내 죄가 용서할 수 없다면,"
rows["271:1618476153"]="요구, 그는 아마도 현상 뒤에 숙취했을 겁니다. 남쪽으로 몇 마일 떨어진 물로 가서 그를 놓칠 수 없습니다.$B$B얼마 전 마을로 돌아다니며 왔고, 떠나지 않았습니다.$B$B지역 주민들은 그를 좋아하고, 재확을 예측하는 능력이 뛰어나죠."
rows["271:1721445914"]="로나는 정말 용감한 모험가가 그녀의 가족의 과목 정원 근처에 많은 말을 구해줬다고 말했습니다.\010바다를 건너간 사람들을 돌볼 수 있도록 제안했어요.\010좋은 길니안  ⁇ 에 관심이 있었나요?"
rows["271:1856235299"]="브루페스트 는 그 나라 에서 가장 좋은 음식 과 음료 를 즐겨 먹는 것 입니다. 과장 은 아닙니다. 그 곳 에는 많은 생생한 손으로 만든 맥주 와 휴일 소시지, 프레스, 치즈 와 다른 종류 가 있습니다. 그 보다 더 좋은 것 은 얼마 되지 않을 것 입니다."
rows["271:1965051516"]="난 다른 사람들보다 램을 잘 뛰는다고 해서 맥주업자들에게 도움이 되지 않을 거란 건 아니지$b$b하지만 기다려, 더 많은 것들이 있어요!$b$b브루페스트에 도움을 주는 것은 세계에서 가장 빠른 양떼를 타고 갈 기회를 얻게 된다는 뜻입니다!"
rows["271:2011033424"]="콩이나 향수를 입으면 누가 사랑에 빠진지 알 수 있을거야.$B$B하지만 기억하세요, 누군가에게 사랑의 표적을 주기 위해서는, 바로 냄새가 있어야 합니다. 남자들은 향기의 향을 좋아하지만, 여성들은 콩을 선호합니다."
rows["271:492941229"]="역사사의 일은 끝나지 않습니다. 항상 중요한 일이 일어나고 있습니다.$B$B당신들의 사람들이 이곳에 왔던 역사를 수집하기 시작했어요."
rows["271:678207961"]="우리는 이 산에 자연의 균형을 회복시킬 수 있는지 확인하기 위해 루안 웰드에 왔습니다.$B$B하지만 아라코아와 우르크컬트의 간섭은 이 일을 어렵게 만든다.$B$B다행히도, 당신과 사미아 같은 사람들이 우리에게 도움을 줄 준비가 되어 있습니다."
rows["271:998587431"]="마일고스의 가장 강력한 요원들은 위쪽의 반지를 보호해줄 겁니다. 혼자만 그들을 이길 수 없습니다. 우리는 드래곤 비행에서 드래크를 불러일으킬 힘을 부여할 수 있습니다. 드래곤의 뒷면에 장착되어, 당신은 오클루스에서 날아와 강력한 드래곤 마법을 지휘할 수 있습니다."
rows["272:1020264582"]="계속해, 거의 도착했어!$b$b제 3번째 여정을 거쳐서 더 쉬워졌다고 해도 좋겠어요!$b$b꼭대기에 가면 \"매우에 있는 술집\"이라는 멋진 숙소가 있습니다. 하지만 무기를 가까이 두세요."
rows["272:1041615433"]="당신은 혼자 할 수 있다고 말하십니까? 이 단순한 어리석은 짓은 아니면 제가 보는 잘못된 자신감인가요?\010네 눈에서 알 수 있어 네가 알야 혼자 이 일을 할 수 있다는 걸 증명해 줘"
rows["272:1094435548"]="바깥은 참 위험하지... 자네에게 가장 필요한 것이 뭘까? 바로 안전이지. 죽음을 피할 수 있도록 내가 도와주겠어! 이 기적적인 불멸의 광석 목걸이를 목에 걸면 설령 영혼의 세계에 가게 됐더라도 다시 돌아올 수 있다고! 마치 소풍이라도 가듯 자네 시체를 찾아가서 생생한 몸으로 부활하는 거지!"
rows["272:1237387507"]="역병지대에서 스컬지의 활동이 열 배로 증가했소. 칼림도어처럼 먼 곳도 스컬지의 침공을 받고 있다는 보고가 올라오고 있소! 어떻게 이런 사태가 벌어졌을까? 어째서 사악한 언데드가 전에는 불가능하다고 생각했던 일들을 저지를까 생각해봤소? 이제 이 세상에 안전한 곳이 존재하긴 하느냐는 말이오!"
rows["272:1254985625"]="잠깐만, 당신 스스로 비행마을을 타고 있지 않은 것 같아요.$B$B여기 있는 다른 괴물들에게도 도움이 되지 않을 겁니다. 그들이 돈을 내면,$B$B관심 있어?"
rows["272:1695564375"]="그의 육체는 우리를 먹이고, 우리에게 힘을 줄 것입니다. 그의 부패한 내장은 침입자로부터 우리를 보호하여 더러운 저기에 던져질 것입니다. 그의 뼈는 우리의 집을 짓게 될 것입니다. 그의 씨는 무한히 순환을 계속할 것입니다.$b$b크로시크에게 힘, 스컬블레이드에게 힘"
rows["272:1836782551"]="모든 것은 정신을 가지고 있습니다. 만약 당신이 그것을 듣고 싶다면 당신이 원하는 모양을 만들 수 있습니다. 금속을 때려서 당신의 뜻을 하도록 강요하는 것은 아닙니다. 그것은 철속의 정신을 듣고 그것이 원하는 모양으로 인도하는 것입니다."
rows["273:1014075237"]="썬더 블러프의 큰 고원에 가서 그 중 하나를 방문해야 합니다. 블러드하프 마을에서 북쪽으로 가는 길을 따라가십시오. 블러프의 밑에 엘리베이터가 있습니다. 당신이 거기에 도착하면 블러프워치 중 한 명에게 추가 방향을 요청합니다."
rows["273:1183094026"]="바람을 마시는 것이오! 대지의 균열에서 순수한 마력이 솟아오를 때 그 신비한 힘의 덩굴이 흑요석 빛깔의 하늘을 비추지. 개울이나 우물에서 물을 마시듯 무릎을 꿇고 틈에서 나오는 마력을 마시면 되오. 가지에 매달린 사과를 따듯 하늘의 덩굴을 잡아당기면 되는 것이지."
rows["273:1340379277"]="아니, 대행사가 서명한 편지로 트랭킬린에서 온 겁니다. 그는 모든 파스트라이더 세력을 동부 국경과 트롤을 철수하도록 요청하고 있습니다."
rows["273:1761306723"]="슈바이저는 오래된 친구예요, 소중한 물건이죠. 친구죠. 그 느낌은 잊혀졌다고 생각했는데\010요즘 티리스팔은 별로 없어서 이 곳을 오브 오브 트랜스록션으로 데려와서 인사할 수 있다고 생각했어요"
rows["273:1877679668"]="여기까지의 적대사건이 일어나기 전에 우리는 지역 나무를 채우기 위해 그들을 준비하고 있었습니다.$b$b최근에는 호드에 대항하여 군대에 투입되고 있습니다. 그들은 꽤 훌륭한 전투기입니다. 열쇠가 있다면, 그것을 사용하지 않는 것은 어리석은 일일 것입니다!"
rows["273:19146097"]="영은 이전에 존재하지 않았던 완전성과 인식의 감각으로 당신을 바라보고 있습니다.$B$B\"내가 큰 짐 을 내 영혼 에서 벗은 것 처럼 느껴요. 곧 영원 히 평화 로 쉬게 될 것 입니다. 이제 이 일 을 알고 있으며, 그 시간 을 인내 로 기다리고 있습니다.$B$B감사합니다, 낯선 사람\"."
rows["273:1926896249"]="아거스에서 맥어리는 우리 도시 중 가장 신성한 곳이었습니다.$B$B만약 내가 당신에게 보행길이 귀중한 광물들로 덮여 있다고 말한다면 믿겠나?$B$B그 날을 갈망하는 거... 얼마나 오래 되었는지?"
rows["273:1986477328"]="어머님, 이 지역은 오래 간가요? 내 친구 \"빅 할크\"와 함께 다음 큰 낚시를 찾아 멀리 여행합니다.$b$b우리는 우연히 이 곳에 달려들었고, 지역 주민들은 물품과 술에 대해 친절했고, 그래서 우리는 여기 머물기로 결정했습니다."
rows["273:318329024"]="되도록 빨리 끝내 주고 싶었다만, 너희는 생각보다... 완강하구나. 어쨌거나 의미 없는 짓거리다. 이 전쟁의 책임은 무모하고 부주의한 필멸의 존재들에게 있다. 나는 할 일을 할 뿐이다. 너희를 멸종시켜야만 한다면, 그리할 수밖에!"
rows["274:1230725733"]="우리 가 최근 에 합류 한 것 이며, 우리 의 전통 을 모르는 것 이 아닐 것 이다. 무롱라데 에서 엄청난 축제가 열리고 있습니다. 이 는 우리 의 장로 들 을 존중 하는 해 의 시기 입니다. 그리고 여러분 은 확실히 초대 됩니다."
rows["274:1276329913"]="성당 옆에서 금판이 있습니다:$B$B\"이곳에 대담레마르의 성당이 있습니다. 가장 귀한 엘프들에게 공훈을 드리며, 이 기념물을 바라보는 모든 사람들이 그의 희생을 기억하게 하여 우리를 이 땅으로 데려오도록 하라."
rows["274:1431908209"]="내가 죽었다고 생각해서 나를 꽉 차고 달릴 줄 생각하는 사람들을 좋아하지 않나? 그래요? 잘해요."
rows["274:168711473"]="내가 여기 있어줘서 고마워요, 이 사고는 내가 겪은 가장 좋은 일이었어요$B$B만약 당신이 다시 보리아 툰드라에 있다면, 내 두발의 이복이신 신자한테 내가 세상에 꽤나 많이 진입했다고 말해줘!"
rows["274:1981887172"]="저는 아라티 계곡에서 아라토르 동맹을 물리칠 수 있는 방법을 찾기 위해 먼 곳을 여행했지만, 그 턱을 입은 암모스 아담 에테른은 내 모든 움직임을 쫓아다니고 있습니다.\010$b\010하지만, 당신 같은 살인자들이 다시 아제로스, 어쩌면 우리는 패배를 할 수 있습니다 얼라이언스 한 번이나 더 이상!"
rows["274:331905039"]="내 용감한 동료 비시 워블본크가 크로스보드에 훈련할 수 있습니다. 하지만 다른 트레이너를 찾고 있다면, 당신은 다르나서스에서 전쟁터 테라스에서 Ilyenia Moonfire를 시도하고 싶지도 모릅니다. 또는 아마도 Exodar 내 트레이더의 Tier에서 Draenei 무기 마스터, Handiir."
rows["274:480442797"]="벽을 따라 두 개의 상기가 우리를 느리게 하고 있습니다. 그들의 보호 없이는 우리의 세력은 손실 없이 요새를 가속히 가할 수 있습니다.$B$B총을 꺼내거나 탄약이 다 끝나기 까지 기다려야 돼"
rows["274:654472100"]="다크월 페어에는 다양한 놀라운 볼거리가 있습니다. 우리는 예고꾼, 콘서트, 낚시 공모전, 그리고 많은 게임을 가지고 있습니다.$b$b우리는 끊임없이 다양한 새로운 볼거리로 페어를 확장하고 있습니다!$b$b더 많은 정보를 얻고 싶은 관광지가 있나요?"
rows["274:677854528"]="이제 우리 둘은 지리적으로도 이웃이 됐어요. 제겐 너무 많은 일을 해줬으니, 내가 조금 도와줄 때가 됐다고 생각합니다. 몇 가지 용의를 요청하고"
rows["274:694442919"]="네, 네... 내 지대에 오신 것을 환영합니다.$B$B그래서, 당신은 어떻게 생각하십니까?$B$B어쨌든 실바나어에서 그  ⁇ 한 엘프들을 없애는게 다행이야$B$B여기서는 도움이 되는 실험과 다른 것들이 많아요"
rows["274:764858400"]="웨이버들은 시간관계를 전문적으로 하는 고고학자들이며, 시간을 짜는 예술입니다.\010시간보행자 중, 우리는 시간 경로의 손상을 복구할 수 있고, 시간 포털을 열고, 그리고 그 같은 다른 작업을 할 수 있습니다.\010이런 것들은 한때 청동색 용 비행에 쉽게 다가왔지만 아쉽게도 지금은 그렇지 않습니다."
rows["274:803378304"]="여행은 그 자체로 보상해, 젊은여. 이야기에서 즐거움을 추구하면 비교할 수 없는 부를 가져오게 될 것이다.$B$B아, 그리고 또 한 가지. 로레워커의 순위에 올라가는 사람들은 매우 특별한 선물을 받았습니다. 구름 위에 타고 갈 수 있는 능력입니다."
rows["274:806400432"]="아니, 마본은 여기 없어서 꽤 오래 안 올 거야$B$B빨리 돌아오길 바래요 큰 상자 가 왔어요"
rows["274:819583046"]="고위집행관이여, 그대가 주장하는 전면 공격에는 생각보다 엄청난 희생이 따를 것이오. 좀 더 치밀한 전략이 필요하오. 마을부터 시작해서 주변 영토도 되찾고, 적군이 데솔름까지 이르는 길목을 전부 차단하는 그런 전략 말이오."
rows["274:9774433"]="이제 승리의 맛을 즐기세요. 다음번 우리가 싸운다면 패배의 쓴맛을 맛볼 것입니다.$b$b사실, 내 다음 맥주에는 \"패의 쓴맛\"이 붙어있다고 생각하지만 그 이름을 가진 맥주를 마실 수 있게 하는 것은 특별한 실패가 필요합니다."
rows["274:980640035"]="아버지는 농촌 중간에 있는 그의 농장집에 살고 있습니다.$B$B그는 거의 모든 비옥한 땅을 소유하고 있으며, 아무도 그것을 잊지 못하게 합니다.$B$B그래서 집을 떠났어 그는 모든 것을 갖고 있다고 생각해요"
rows["275:1012479288"]="원자성  ⁇ 딩 기간 동안 라그나로스 불의 주인이 내 왕자인 공중 공주를 삼키려고 했습니다.$B$B<데미트리안은 머리를 숙이고 분노로 얼굴을 왜곡한다.>$B$B그의 이름을 말해라 내가 너의 내장으로 이 황폐한 수용소를 장식할 것이다.\010"
rows["275:1066886981"]="그라불루스는 살덩이 거인 군대의 첫 번째 병사이다. 놈은 낙스라마스의 역병 걸린 진흙괴물을 체내에 넣고 다니며 적의 몸에 그 살아 있는 액체를 주입하지. 이 공격을 당한 이는 두려움에 아군이 있는 곳으로 도망가게 마련이고, 그러면 모두 함께 몰살당하고 만다."
rows["275:1146452059"]="과거에는, 즉, 제왕과 그의 형제들이 창조의 첫 시대라고 부르는 시대가 있었습니다.$B$B그리고 결국 자신을 형성자라고 부르는 사람들에 의해 버려지는 사람들은 바로 그들이었습니다.\010"
rows["275:1231308062"]="이리던은 용마우에게 그들의 지도자를 넘겨주었고, 이 오크는 알렉스스트라사스를 체포하고 감옥에 넣은 자였죠.$B$B그리고 그는 내 친구를 데려갔어"
rows["275:1257045552"]="사냥꾼, 예술가, 예술$b$b저는 예술을 통해 사냥의 야만성을 담기 위해 왔습니다.$b$b우리는 낯선 땅에서 살고 있으며, 알려진 세계에서 우리의 사냥에 있어서 이상한 생물들을 아는 사람은 거의 없습니다.$b$b내 예술을 통해 네스링워리의 성공과 당신의 성공을 증명할 수 있습니다."
rows["275:14468022"]="그는 항상 마법의 유물을 발견하는 것에 대해 이야기했습니다. 아즈샤라는 그 유물이 많았다고 말했습니다.$B$B마지막으로 들은 건 그가 그 아르크마지인  ⁇ 렘과 친구가 되고 싶다는 거야\010"
rows["275:1622903291"]="블레이드즈 엣지 산맥은 좋은 기회의 장소입니다. 어떤 사람들은 그러한 기회를 활용하는 것에 관한 문제에서 다른 사람들보다 우월하다고 생각하는 것이 얼마나 불행한지.$B$B젠아리온 탐험대는 우리가 여기서 무엇을 할 수 있고 할 수 없는지 말해줄 수 있는 사람이라고 생각합니까?"
rows["275:1737809700"]="밤 중순은 사냥꾼의 개인적인 산입니다. 나는 더 빠르고 강하거나 더 악의적인 정신을 가진 말을 본 적이 없습니다. 그리고 그녀의 라이더는 더 이상 temperamental입니다! 모든 사람들이 그녀의 멀리 떨어져, 그들은 밤 중순에서 머리 위에  ⁇ 을 얻을 수 없도록 또는 애트먼의 때림에서 얻을 수 있습니다."
rows["275:1970648926"]="용은 왕실의 표면 뒤에 숨어있어요. 태블릿은 그녀가 누구인지 드러낼 것입니다. 내가 본 것이 사실이라면, 나는 이 전투에서 살아남을 수 없습니다. 친구."
rows["275:225035528"]="스컬지는 공격당하는 장소에서 작은 스테디닝 포인트를 설치하고 있으며, 시골에서 통신과 다른 지원을 받고 있습니다. 우리가 알 수 있는 것 처럼, 그들을 뿌리내리는 유일한 방법은 그 점을 둘러싸고 있는 지상군을 죽이는 것입니다."
rows["275:729553313"]="빨리 배우면 나쁘지 않아서 잘 해야만 하는 일을 잘 해봐요. 그렇게 하기 위해 필요한 시간 동안. 이제, 저는 당신을 스나르러로 보내야 한다고 두려워합니다. 더 많은 것을 배우기 위해. 그가 무엇을 가르쳐 줄 수 있는지 알아보세요. 하지만 그의 분노한 말을 듣지 마십시오."
rows["275:842824875"]="사피론은 한때 노스렌드의 산악 지대에 살던 고귀한 푸른용이었지. 하지만 얼어붙은 북쪽 땅을 진군하던 아서스에게 살해당했고, 부활하여 그를 섬기게 되었다. 사피론은 영원토록 켈투자드의 둥지를 지키며, 감히 그의 주인에게 다가가려는 자를 기다리고 있지."
rows["276:1001351109"]="두루탄과 오르그림은 테로카르 숲으로 갔고, 괴물이 거의 죽였죠. 드레네이들이 그들을 구하지 않았다면..."
rows["276:1127453322"]="계속 싸워라 오늘 흘린 피가 영웅들의 피와 섞여 있다는 것을 알라. 죽음에서도 우리 영혼들은 여러분의 친척과 세상을 구해내는 승리를 알게 될 것이다. 절망에 굴지 말라, 친구들, 우리가 직면한 악마들이 확실히 그것을 즐겨 먹게 될 것이기 때문이다."
rows["276:1390646942"]="로켓 장 Fuselage는 X-52 네더 로켓을 만드는 데 자원봉사자를 요청했을 때, 저는 보안 부문에 저의 서바이오를 제출했습니다.$B$B불행히도 남은 유일한 직위는 엔지니어장이었는데 다행히 제 어깨를 돌볼 수 있는 엑시롤이 있어요"
rows["276:179637631"]="그림자 사냥꾼 데냐이는 이 전지대를 건설하기 위해 나를 작은 건설자들과 함께 보냈고, 우리는 겨우 건물을 완성했고, 그는 이미 보고서를 요청하고 있습니다!$B$B물품이 필요하다면 몇 가지 물건을 제공할 수 있지만 아직 첫 배송을 기다리고 있습니다."
rows["276:1815568005"]="알렉시 말 좀 들어봐요, 전염병 때 머물게 된 바보였는데, 이 곳의 다른 혐오보다 더 낫지 않아요.$B$B걱정 마요, 우리는 바로프의 마지막 살아있는 아들인 상속자로 슐로만스와 주변 땅을 되찾을 겁니다."
rows["276:1843076852"]="이봐, 우린 지금 이 엉망에 빠져있어요. 우리는 아이스크로wn에서 우리군과 합류해야 합니다. 스컬지 그리고 드라카리$B$B고산군에게 여기 오기가 실수라고 말했지$B$B어떻게 도와줄 수 있는지 보자"
rows["276:1947274590"]="넌 내 조직에서 내가 찾고 있는 쓰레기 같은 놈이야 우린 사우스시 프리부터즈의 독립적인 프랜차이즈야"
rows["276:2089697887"]="주인님, 모든 것이 착착 진행되고 있습니다. 세나리온 수풀에서 소규모 원형을 실험한 결과, 매우 성공적이었습니다. 현재 아래쪽 안마당에서 두 번째 폭탄의 연료를 주입하고 있습니다. 그리고 이곳으로 나머지 부품을 가져올 전령을 투렘으로 보냈습니다."
rows["276:340995434"]="명예의 여자들은 이 괴상한 땅에서 피를 흘리고 젊음을 잃었지만 여전히 정신을 고르게 유지합니다!$B$B이제, 당신과 당신의 동원들 아제로스 당신은 우리에게 희망이 주어질 것입니다. 언젠가 우리는 고향으로 돌아갈 수 있습니다."
rows["277:1060440151"]="많은 사람들이 톨스트라이더가 웃기 좋은 애완동물이라고 말하지만 지능과 충성심 때문에 여러 상황에서 적응하기 어려운 존재입니다."
rows["277:1094170386"]="이제 이 전쟁을 이길 수 있게 해!$B$B동쪽의 흉터있는 지형을 가로지르며, 얼라이언스는 그들의 해안 요새들 사이에 육지 연결을 건설하기를 희망한다. 그들은 불모의 땅의 중심에 이곳에 요새를 건설할 계획이다.$B$B안 지낼 거야"
rows["277:1442808325"]="내가 칼 워튼, 빌그워터 트릭스$B$B가봐, 그 공을 둘러봐, 진짜 원하는 트릭을 선택해!$B$B이 트릭은 정말 멋지죠. 위험하고 죽음의 위협이 되는 트릭은 자랑스러워할 수 있는 트릭입니다.$B$B보고 나면 알릴 거고, 거래할게"
rows["277:1503301240"]="제 형제자매  ⁇ 의 도움으로 저는 에버룩에서 이 지역에 있는 52누가 로켓을 필요로 하는거야? 당신은 자신의 임플로더 빔을 만드는 법을 배울 만큼 숙련된 거북공학자가야?\010"
rows["277:1586527871"]="지구보호가 회복하기 시작했을 때 그는 조용하고 평화로 가득 차서$B$B죽음의 날개가 사라진 후, 그들은 다시 목적이 없는 상태가 될 것입니다."
rows["277:1601306694"]="이 정도면 만족하십니까?"
rows["277:1768626585"]="<조모 게아가 웃는다.>$B$B내가 늙었으니 내 때가 이르렀으니 내가 지나가면 내 영혼은 영의 영역으로 옮겨져 나와 함께 나의 조상들과 함께 서 있을 것이며, 거기서 우리 백성들을 돌볼 것이다.$B$B가라드가 살아있을 때 카슈르 어머니의 의무는 지금과 같았습니다."
rows["277:1808594595"]="베리안도 널 보냈어?$b$b제이나의 눈은 악성적으로 깜박이는 것 같다.$b$b다른 방법으로 해봅시다. 제 자리에 서세요. Kirin Tor의 리더가 여러분이라고 상상해 보세요. $p세계에서 가장 영향력 있는 성작 아제로스!$b$b당신 은 어떻게 할 것 입니까?"
rows["277:2132361557"]="윈터프링에 사는 윈터폴 펄볼그들은 한때 우리의 동맹이었지만 어느 날 모든 것이 바뀌었습니다.$B$B그들의 최고 지도자의 이상한 요구에 의해, 그들은 우리의 부족을 포함한 접촉한 모든 다른 사람들을 공격하기 시작했습니다."
rows["277:264256913"]="서, Farstrider Solanna는 Zeb'Tela와 Zeb'Nowa에 대한 공격이 진행되고 있다고 알려줍니다. 그녀는 유망하고 젊은 후보를 모집해 상황을 도와줬습니다. 또한, 위층의 약사는 트롤도 도울 수 있다고 생각하는 해결책을 언급했습니다."
rows["277:356659983"]="네가 없었다면 이미 악마들이 우리를 몰아넣었을 것이고, 아니면 블랙 드래곤 비행에 의해 튀겨버릴 것이라고 말할 용기가 있다!$B$B아시다시피, 우리는 우리 아들 중 한 명을 값싸게 팔겠다고 언급했지"
rows["278:1074971464"]="할아버지가 말했듯이, 당근은 춤추지 않는다!$B$B뭔가 우리 밑에서 채소를 꺼내려고 하고 있어요!$B$B작물이 평화롭게 지내고 싶다면 저 아래의 버미트를 죽여야 돼"
rows["278:1174225782"]="검은색, 회색, 어두운 보라색은 정해진 색입니다. 당신이 패션 스트리트 친구의 잘못된 쪽으로 길을 잃지 않도록 하십시오. 보웬 브리즈보이스는 당신이 그렇게하지 않는 것을 볼 수 있습니다. 당신은 그를 찾을 것입니다 도시 남서쪽의 다리의 다른 쪽에서 콜드 하더 맨어."
rows["278:1318810900"]=" ⁇ , 당신은 올라와야 할 것 같습니다 썬더 블러프 북쪽으로 가서 블러드하프 마을을 떠나 썬더 블러프엘리베이터를 타고 꼭대기에 올라가면 블러프워치의 도움을 요청할 수 있을 겁니다."
rows["278:163565623"]="...거짓말이 싫지만, 그렇지$b$b이 나무들이 생산하는 양자물은 놀라운 치유 기능을 가지고 있습니다. 만티드는 그것을 충분히 섭취하지 못합니다. 그들은 그것을 소비하고, 그들의 무기와 건축에서 사용합니다. 심지어 전설에 따르면 그들은 그들의 위대한 영웅들을 그 물질로 embalm합니다."
rows["278:1660339853"]="저는 돌과 철로 된 이 인간 도시들을 좋아하지 않습니다. 큰 짐승 을 추적 하는 잿빛 골짜기의 숲을 선호 합니다. 하지만 내 사랑하는 형제 카에브루스는 우리 방법 으로 인간을 훈련시키는 것이 유익하다고 느꼈습니다. 그래서 제가 그를 존경하고 제 서비스를 제공 할 때, 저는 그것을 좋아할 필요는 없습니다."
rows["278:1990557557"]="리테가 쉐이디 레스트 인의 화재에 관여한다면 그를 찾아서 그에 대한 답을 얻어야 합니다.$b$b오그론을 찾아 보내서 남동쪽으로 갔어요, 메인도로로 습지를 지나갔어요."
rows["278:2052124854"]="이 최고 집행자 마브렌이 지치고 있습니다. 우리는 파스트라이더들을 동부 국경에서 끌어내지 않을 것입니다. 그는 그것을 알고 있습니다. 또한 아우리페로스 부인도 이 문제에 대해 완전히 동의하고 있습니다. 그녀가 다른 말을 하지 않는 한, 우리는 자리를 유지합니다."
rows["278:516398053"]="- 안 돼, 천천히 해$B$B슐로마네스는 그들의 교육의 주요 근원입니다. 그리고 그 곳에서 종속자들이 퍼져나가고 결국 우리 사회로 진입합니다.$B$B그래서 우리는 원천을 공격해야 합니다. 저주받은 종파의 심장입니다."
rows["278:623128856"]="마을에는 그런 곳이 없습니다. 썬더 블러프의 높은 고도가 있습니다. 블러드하프 마을에서 북쪽으로 올라갈 때까지 블러프의 밑으로 오십시오. 엘리베이터를 타고 꼭대기에 올라가서 블러프워치와 이야기하십시오. 여러분의 조상들이 여러분을 지켜 주시기를 바랍니다."
rows["278:661322226"]="예, 하지만 식물학에 대한 실력을 가지고 있다면 더 유익하게 될 것 입니다. 여러분은 특별한 씨앗을 키우고 재배할 것입니다. 여러분이 받을 '영원 녹색 팟'은 초보자에게도 무언가를 키울 수 있게 해주지만, 식물학에 대한 실력을 보여준 사람은 더 풍요로운 결과를 얻을 것입니다."
rows["278:894890008"]="경비자들은 타임워커의 학자, 스카우트, 연구자, 스파이입니다.\010우리는 시간 흐름을 관찰하고 기록, 조사, 그리고 시간적 조작과 특이한 현상을 보고합니다.\010물론, 이 이상한, 시대를 초월한 섬에 타임워커들의 관심을 끌었던 것은 감시자였습니다."
rows["279:1155012510"]="오늘 못 봤는데 너무 이상해 생각했는데 아침에는 걸어서 일하러 데려다 주죠$b$b그는 친절한 마음을 가지고 있습니다. 싱그루프의 연습생 생활을 비방하는 것은 부끄러운 일입니다. 그는 매우 재능있는 용기 제조업자입니다.$b$b만약 그를 본다면, 오늘 아침 걸을 수 없었다고 말해줘"
rows["279:1469891725"]="죽음에서, 세계의 동물들은 우리에게 생명과 보호를 동시에 제공합니다. 만약 당신이 그들의 희생에 대한 적절한 존중을 제공할 수 있다고 생각한다면, 다르나서스 더 많은 것을 배울 수 있도록"
rows["279:1531042036"]="야외에서 사냥을 좋아하는 사람이라면, 펠우드의 ത്രെ앙트와 언'고로의 래셔가 잎을 먹기 좋은 곳이다.$B$B만약 여러분이 더 위험성 있는 사람이라면, 디레 몰의 동쪽과 서쪽 날개가 야생 잎의 거의 무한한 공급을 제공할 것입니다."
rows["279:1617569625"]="죽음에서, 세계의 동물들은 우리에게 생명과 보호를 동시에 제공합니다. 만약 당신이 그들의 희생에 대한 적절한 존중을 제공할 수 있다고 생각한다면, 다르나서스 더 많은 것을 배울 수 있도록"
rows["279:1705936014"]="크리스탈 레이크에서 낚시를 하는 것만큼 좋은 일은 없습니다. 아놀드 리랜드는 저를 가르쳤어요. 보통 캐날드 지역의 항구에서 낚시를 하는 것 처럼요. \010그리고 그가 당신에게 이야기한 어떤 이야기도 믿지 마세요."
rows["279:1933978858"]="네파리안은 고대 성당에 의해 보호받고 있습니다. 그 이유는 내가 성당의 성당에 들어갈 수 없거든요."
rows["279:1991710725"]="저는 그들이 저를 이 도시를 떠나게 한 것을 믿을 수 없습니다! 사고로 인해 피해를 입은 대부분의 거북이들은 몇 주 안에 일종의 인간형 형태를 되찾았으며,\010게다가, 우리는 달걀을 필요로!\010"
rows["279:306130380"]="<앞에 있는 트롤은 발끝부터 발가락까지 긁힌 상처가 있고, 얼굴에 신선한 조각이 들어서서 입술이 비워져 있습니다.>$B$B-  ⁇ !$B$B알다시피, 트롤스 와이퍼스, 문제는 야생 와이퍼스를 두 가지로 양육하는 것입니다."
rows["279:593933057"]="타르시스는 당신을 목걸이에 약하게 붙잡고 있습니다. 죽음에서도 그의 눈에 상상할 수 없는 힘을 볼 수 있습니다.$B$B그럼 주의 깊게 들어봐요, 더 많은 말도 안 되는 말이 내 입에서 빠져나오려고 합니다. 이 성곽 안에 내 생애 작품이 있습니다."
rows["279:771472312"]="우리가 어떤 것도 낭비하지 않는 것을 믿는 문화로서 우리가 어떤 생물을 죽이는 것을 강요당할 때 우리는 그 희생이 헛되지 않았는지 확인하기 위해 최선을 다합니다.  \010만약 당신이 죽인 짐승의 피부를 제대로 가져가는 방법을 배우고 싶다면,"
rows["279:979057621"]="아직까지 크리스탈 노출이 충분하지 않은데 그 소년은 아직 말할 수 없을 정도로 멍청하지만, 그 병을 가져오는데 당신이 해준 것에 감사해요.$B$B이제 9명의 아들이 더 남아있어요$B$B토커스의 두 머리는 고개를 숙이고 있습니다.$B$B우리 손에서 하나를 빼앗으려 한다면, 싸게 팔아줄게"
