rows["27:994236010"]="- 제발, 날 밝게 해 "
rows["280:1047850366"]="숲 에서 어떤 생물 이도 코랑 을 피할 수 없다. 그 는 추적 하는 데 있어서 그렇게 능숙 하다. 만약 당신 은 절반 정도 성공 을 도 하고 싶다면, 그 의 가르침 을 들어보는 것 은 좋다.  \010그를 추적하는 짐을 덜어주고 지도에 그의 위치를 표시해 줄게 되는데"
rows["280:1287753262"]="더는 이목을 끌어서는 안 되오. 당신에게 윈탈루스를 찾으라고 지시한 자들에게 돌아가서 아무것도 찾을 수 없었다고 전하시오. 그런 다음 날 다시 찾아오시오. 그 말을 전하는 순간 난 당신이 할 일을 마쳤다는 걸 알 수 있으니까 말이오. 그러면 죽은 윈탈루스의 비밀을 알려주리다."
rows["280:1604267312"]="제디스 바로프의 일기에는 죽은 자들에 대한 거론과 험담이 가득하다. 책의 마지막에 felth bag을 만드는 데의  ⁇ 질 패턴이 보인다. 이 가방은 마녀들이 영혼 조각을 저장하는 데 사용한다. 당신은 이미 이 가방을 만드는 방법을 알고 있습니다."
rows["280:1649193058"]="이국 국민 오그리마알다시피 위험한 교단이 우리 도시를 찢어 버릴 위협이 됩니다. 노스렌드국민의 원수인, 모든 사람들이 오그리마 수색과 조사를 받아야 합니다."
rows["280:1667080393"]="카엘타스가 마을을 평평하게 만들었을 때, 저는 아무것도 할 수 없었습니다. 그의 마법은 이미 저를 탑에 봉쇄했고,$B$B그리고 여전히 그들의 목소리는 멀리서 부르고, 밤중에 날 깨우치고 있습니다. "
rows["280:194994593"]="다음 에 무슨 일 이 일어날 것 입니까?\"라고 자신 에게 물어볼 수 있습니다. 그 답 은 나 와 같습니다. 우리 예술 을 더 많이 배우려면 아이언포지라는 놀라운 곳으로 바다 를 건너 여행 해야 합니다."
rows["280:1958840621"]="우리 탐험대는 포털을 안전하게 통과하고 트랄마르라는 새로운 기지를 세웠지만, 볼 수 있듯이, 불타는 군단는 들어와서 우리 형제들과 우리를 끊었다. 분명 악마들은 어두운 포털을 되찾고 아제로스에서 보강을 모집하는 것을 막으길 바라고 있습니다."
rows["280:197829000"]="돈 때문이 아니죠! 우리는 관대한 기부금 - 일부 극히 큰 기부금 - 을 받지만, 우리 여행하는 공연자 그룹은 이 전쟁으로 황폐화된 세상을 밝히는 필요성으로 창의적으로 자극받습니다. 우리에 대해 걱정하지 말고, 대신 우리가 당신을 가장 잘 즐겁게 하는 방법에 대해 걱정하도록 해 주십시오."
rows["280:357887916"]="오, 그 다릴 리크누스런은 훌륭한 요리사입니다. 그는 치리 너무 뜨거운 당신이 그것을 통해 강철을 가열 할 수 있습니다! 나는 그가 당신에게 레시피를 가르쳐 줄 것 같지 않지만, 그는 확실히 당신을 좋은 요리사가 될 수 있도록 도와줄 것입니다. 당신은 그를 발견 할 것입니다 브론즈  ⁇ 에 o'er 대 동북쪽의 큰 갈고리."
rows["280:496734278"]=" ⁇ 족에게 맡겨서 광산 전문가를 보내 아이언포지 어떻게 채굴해야 하는지 알려줘요. 어떤 바위에서  ⁇ 을 뽑는 것이 얼마나 어려운지?"
rows["280:860959798"]="브리즈트!$B$B보안 레벨 델타 터미널인 매트릭스 펀코그래프 3005 D 스트로크에 오신 것을 환영합니다.$B$B빨간색 펀치 카드 확인됐습니다.\01001001000 01101111 01110111 00100000 01100001 01101101 00100000 01001001 00100000 01100100 01110010 01101001 01110110 01101001 01101110 01100111 00111111"
rows["281:1213406491"]="만티드 들 은 전쟁 의 욕망 을 제외하고는 생각 이 거의 없는 상태 에서 태어난다. 무더기에 참여 하는 것 은 단순히 문화적 인 행태일 뿐 아니라 우리 가 신체적 으로 성숙 할 수 있는 촉매제 이다.$B$B전투에서 돌아온 사람들만이 무더기에서 태어나서 완전히 의식하고 개인 시민으로 발전할 수 있습니다."
rows["281:1375435108"]="당신은 황제 비지어 Zor'lok의 |cFFFF0000|Hspell:122713|h[포스 앤 버브]|h|r. 당신이 또는 동맹이 당신의 치유 능력을 사용하여 당신을 살아있게 하기 위해 |cFFFF0000|Hspell:122706|h[소리 취소] |h|r 구역 중 하나를 입력하려고 시도하십시오."
rows["281:1469180818"]="전 하루 종일 제펠린의 부품들을 찾아다니는데 프레즈가 시간당 임금을 내는데도 괜찮지 않아요. 하지만 그 때문에 여기 있지 않나요?"
rows["281:1473834573"]="여기부터 문관에서 3가지 방향으로 이동할 수 있습니다. 내 뒤에 있는 계단은 대축구실으로 향합니다. 그 곳에서 손님들이 현재 즐겁게 놀고 있습니다. 저는 근처의 스테이블을 냄새가 맡을 수 있을 것이라고 확신합니다. 그리고 복무관의 입구는 문관 옆에 있습니다."
rows["281:1833505451"]="자리를 지켜라! 자리를 지켜라! 얼라이언스와 호드의 아들딸들이여! 나의 형제자매들이여! 너희 눈에서 내 심장조차 움츠러들게 할 두려움을 본다. 언젠가 우리의 용기가 꺾이고 친구를 버리며 동료들과의 연대가 무너지는 날이 올지도 모른다... 하지만 오늘은 아니다!"
rows["281:1833505464"]="영토를 사수하라! 얼라이언스의 아들 딸들이여, 호드의 형제자매들이여! 그대들의 눈동자에서 내 가슴을 서늘하게 한 것과 같은 공포를 보았다. 우리의 용기가 사그라져서 친구들을 배반하고 우정을 깨뜨릴 날도 있을지 모른다. 하지만, 그날이 오늘은 아니다!"
rows["281:1972882045"]="안녕하세요, 모험가, 저는 린우보쇼입니다.  ⁇ 다자르의 상인이에요. 저는 남해에서 왔습니다.$B$B만약 당신이 내 부족에게 당신의 가치를 증명한다면, 내가 교환을 할 수 있습니다."
rows["281:2124723792"]="이 곳까지 우리를 인도한 것은 하나님의 비전이었습니다. 우리 모두는 평화의 희망으로 가득 찬 금색 꽃이 있는 계곡을 꿈꾸었습니다.$b$b우리 보령자 바인 블러드후프도 이런 꿈을 꾸었다$b$b하지만 레즈라의 비전은 우리에게 길을 제시했고, 이제 우리는 여기 있습니다."
rows["281:290907942"]="드레드스티드를 불러오려면 먼저 더 큰 소환의 회로를 만들어야 합니다.$B$B더 큰 소환의 원에는 세 가지 강력한 도구가 필요합니다. 데트무라의 벨, 블랙 마치의 바퀴, 그리고 종말의 촛불."
rows["281:410718245"]="맞아요, 회의, 그럼 좀 더 논의해 보죠.$B$B사실, 루안 웰드에서 목재와 가축을 수집하는 것은, 당신이 책임지는 것이,$B$B우린 그 자원이 필요하지만 당신은 Cenarion 탐험의 드루이드가 방해를 받을 수 있게 해줬어!"
rows["281:713634097"]="난 살아있어요, 살아있어요, 내가 살아있어요! 오, 너무 앞뒤가 안 돼서 여러분께 제가 여러분을 사랑한다고 말해주길 바래요."
rows["281:8736271"]=" ⁇ 굴은 유령으로 가득 차 있어$B$B'더 트와일াইট'의 해머가 산 꼭대기에 서 있는 날, 부당한 사람들은 동굴에 던져졌습니다.$B$B젠장, 젠장, 젠장, 젠장, 젠장, 젠장, 젠장, 젠장, 젠장, 젠장, 젠장, 젠장, 젠장, 젠장, 젠장, 젠장, 젠장, 젠장, 젠장, 젠장, 젠장, 젠장, 젠장, 젠장, 젠장, 젠장, 젠장, 젠장, 젠장, 젠장, 젠장, 젠장, 젠장, 젠장, 젠장, 젠장, 젠장, 젠장, 젠장, 젠장, 젠장, 젠장, 젠장, 젠장, 젠장, 젠장, 젠장, 젠장, 젠장, 젠장, 젠장, 젠장, 젠장, 젠장, 젠장, 젠장, 젠장, 젠장, 젠장, 젠장, 젠장, 젠장, 젠장, 젠장, 젠장, 젠장, 젠장, 젠장, 젠장, 젠장, 젠장, 젠장, 젠장, 젠장, 젠장, 젠장, 젠장, 젠장, 젠장, 젠장, 젠장, 젠장, 젠장, 젠장, 젠장, 젠장, 젠장, 젠장, 젠장, 젠장, 젠장, 젠장, 젠장, 젠장, 젠장, 젠장, 젠장, 젠장, 젠장, 젠장"
rows["281:922108702"]="몇 년 전, 저는 지역 내 한 무르록 문제 를 해결 하려고 애쓰면서 비극적 으로 죽었습니다. 하지만, 저는 여신 과 함께 있는 대신, 가족 과 친구 들 을 지켜보는 데만 만족했습니다.$B$B이제 그들은 모두 사라졌거나 더 나쁜 것은 죽은 것이고, 남아있을 이유가 하나밖에 없습니다.$B$B복수"
rows["281:941138538"]="환영합니다, 동맹님.$B$B\"호드\"라고 부르는 짐승들은 이 숲을 파괴하고 있습니다. 그들의 끔찍한 돌 리본은 우리의 땅을 깎아내고, 우리가 사냥하는 동물을 겁에 주고,$B$B친구, 어떻게 블랙마우가 당신의 이 '얼라이언스'에 합류할 수 있을까요?"
rows["282:1216992193"]="우리가 수집한 마지막 상품은 다음 $2113w일 동안 실리투스로 배송될 것 같습니다. 그리고 그렇게 되면, 누군가가 와서 Ahn'Qiraj 밖에서 있는 스카라브 데이에  ⁇ 을 울려들어 문들을 열어야 합니다. 그때 우리의 붕대가 유용하게 쓰일 것입니다."
rows["282:1272593401"]="우리는 다른 길을 건설하고 있습니다 스톰윈드 이 벽이 제거되면 항구만 해... 하지만 이 미친 왜기는 전체 분할을 평평하게 만들 만큼의 먼지를 가져왔다!$B$B알렉스톤 선생님이 그녀를 고용했을 때 무슨 생각을 했는지 모르겠어요... 그녀는 거칠고, 악순위하고,"
rows["282:1301297671"]="우리가 이 땅을 치유하고 상처를 치료하려면 많은 일이 있습니다. 하지만 당신의 행위 덕분에 우리는 더 이상 Y'Shaarj의 일곱 숨의 그림자에서 일하지 않을 것입니다.$b$b시간이 지나면 샤가 사라지고 네 이름은 마지막 황제의 존경을 받으며 기억될 것이다."
rows["282:1598681619"]="우리 카라밴은 하루에 두 번이나 나가지만 스컬지 디디어와 그의 무얼들이 전선에 배송을 못 내도록 막기 위해 최선을 다해왔습니다."
rows["282:1754980417"]="우리가 상자 안에 있는 마을에 들어갔을 때, 그들은 우리가 아즈하라 어딘가에 배치될 것이라고 말했어요.$B$B내가 묻습니다. 누가 상자 안에 있는 마을을 준비하고, 그것을 먹고 살 만큼 충분한 음식을 공급하지 않는가?$B$B미크로 메차치킨이 어떻게 됐는지 모두 알고 있습니다."
rows["282:285533060"]="저쪽의 '서너송' 가게에 누가 들어올까 궁금했어요$B$B<그린필드는 어깨를 비추고 윤에게 물결을  ⁇ 다>$B$B시장에 와서 가장 크고, 가장 맛있는 채소를 가져오면 씨앗을 어디서 얻었는지 말해줘!"
rows["282:605891639"]="이 성전의 기억은 두꺼운 안개가처럼 내 마음을 덮고 있지만, 일관된 이야기로 집어넣을 수는 없습니다. 이 장소는 한 번 나에게 어떤 의미도 있었습니다. 그 기억을 회복할 때까지, 저는 제 일부가 없어진 것처럼 느낄 것입니다.$B$B아마도 드레네이가 내가 잃어버린 것을 되찾을 수 있을지도 모릅니다."
rows["282:700353664"]="|cff6600aa 희귀 도전자:|r\010  라저그린: $8088w-$8087w\010  분포: $8090w-$8089w\010  디피 & 더이피: $8094w-$8093w\010  메카 브루스: $8092w-$8091w\010  블링트론 3000: $8098w-$8097w\010  로-슈무바: $8096w-$8095w\010  곰과 여인 페어: $8082w-$8081w\010  미 ⁇ 스 디그스: $8100w-$8099w\010  블라인드 히어로: $8102w-$8101w"
rows["282:850470280"]="|cff6600aa 희귀 도전자:|r\010  라저그린: $8048w-$8047w\010  분포: $8050w-$8049w\010  디피 & 더이피: $8054w-$8053w\010  메카 브루스: $8052w-$8051w\010  블링트론 3000: $8058w-$8057w\010  로-슈무바: $8056w-$8055w\010  곰과 여인 페어: $8042w-$8041w\010  미 ⁇ 스 디그스: $8060w-$8059w\010  블라인드 히어로: $8062w-$8061w"
rows["283:1040723673"]="안녕하세요 다시요 $p두 번째 기회를 즐기고 있어?$B$B만약 당신이 스카이파이어가 떠나기 전까지 모험을 계속한다면, 당신은 자동으로 정상적인 시간대에 다시 합류하고 다시 라이온스 랜딩을 발견할 것입니다.$B$B아니면 다시 사자의 착륙으로 돌아가면 알려줘요"
rows["283:2000293669"]="여러분께 진심으로 감사드리죠. 이 무살 폭탄은 가로쉬의 잔인함을 보여주는 증거입니다. 아제로스 전쟁의 가장자리에 있습니다. 죄송합니다, 하지만 저를 용서해 주세요."
rows["283:514107892"]="마법은 미묘한 악동보다 더 많은데... 하지만 이미 알고 있는 사람과 얘기하고 있어요.$B$B네가 내게 와서 배울 거야 내가 말하는 대로만 하면 네가 할 거야"
rows["283:857525415"]="안녕하세요, 젊은 사람, 그리고 환영합니다 썬더 블러프이 세상 모든 짐을 피신할 수 있을 겁니다 호드 여기 오신 것을 환영합니다.$B$B현재와 과거의 영들이 이 신성한 장소에서 살아나고 있습니다."
rows["283:949907723"]="스톰윈드의 공원이 파괴되고 대부분의 밤 엘프들이 들어서면서, 가난한 불행한 영혼들은$B$B북부 착륙선에서 내려가는 계단들이 있는데..."
rows["284:1126358452"]=" ⁇ 더란은 불의 주인에게 전혀 알지 못했고, 내 주께서 반응하기 전에, 래그나로스의 전설적인 해마르인 실푸라스는 무자비한 공을 치고,  ⁇ 더란은 완전히 패배했다.$B$B불의 주인이 내 주님의 본질을 즐겼지만 그를 완전히 삼킬 수 없었다"
rows["284:1216655219"]="순례자의 보너스는 자신의 행운을 생각해보고 주변 사람들과 공유하는 시간입니다.$B$B내 멀고어 그리고 호드우리는 많은 열매를 함께 즐길 수 있는 집과 친구를 찾았습니다.$B$B우리의 동맹국들 모두가 함께 축하하고 축하할 수 있기를 바랍니다."
rows["284:1460014585"]="포세이큰의  ⁇ 은 이렇게 흥미롭고 강한 조화로 만들어집니다. 당신은 그렇게 생각하지 않습니까? 그것은 실패로 자신을 독성하는 능력이 있습니다. 나는 믿습니다. 당신에게 행운을 위해, 언더시티의 닥터 허버트 할세이 이미 필요한 연구를 수행했습니다. 당신이 그를 방문할 수 밖에 없습니다."
rows["284:1785882465"]="카타킬스마는  ⁇  모로그에서 혼란을 일으켰습니다. 트로그들은 지금까지 볼 수 없는 숫자로 표면에 올랐고, 우리의 전통적 적인 프로스트마인 트롤들을$B$B아이언포지는 내 산악 회사로 문제를 해결하는 데 도움을 보냈습니다."
rows["284:1795960059"]="저는 얼마나 많은 번이나 호수나 강의 바닥에서 아름다운 광물 동맥을 보았는지 기억이 나지 않습니다. 저를 조롱하는 채 깜박여서요. 저는 광물 채굴을 위해 손을 잡고,"
rows["284:1908616881"]="브리즈트!$B$B보안 레벨 델타 터미널인 매트릭스 펀코그래프 3005 D 스트로크에 오신 것을 환영합니다.$B$B터미널 기능에 액세스하려면 빨간색 펀치 카드를 가지고 있어야 합니다.\01001010011 01101000 01101111 01110010 01110100 00100000 01100001 01101110 01100100 00100000 01110011 01110111 01100101 01100101 01110100"
rows["284:422383160"]="<필드마셜 챔버스  ⁇ 어들어요>$B$B그래서 디디에르에게 물품을 한 조각으로 가져오는데 도움을 준 거잖아요?$B$B저한테서  ⁇ 게 해줘서 내가 서명할 수 있어\010"
rows["284:843158445"]="마을 사람들에게 사랑 표지판을 주면, 당신은 다른 선물을 받을 것입니다. 일부는 당신이 보관하고 사용하기를 원하지만 다른 것들은 묶어서 좋아하는 영웅에게 제공 될 수 있습니다! Kwee Q. Peddlefeet을 방문하여 그들을 돌려주십시오.$B$B퀴는 볼바르, 마그니, 타이란데 근처에서 발견된다."
rows["284:898887488"]="내가 여기서 꽤나 잘 일을 해냈어, 멀리서 보인 레글쿠트가 날 경고하려고 했지만, 내 방목은 마침내 날 잡았다.$B$B제트 고르의 유적들을 연구하러 왔지만, 제 길을 걸으면서 레지온에 충돌했지"
rows["285:1483548428"]="우리는 드래곤마우들이 너무나 많은 고통을 겪었고, 그림 배톨에서 패배했고, 아웃랜드년에 수많은 위대한 전사들을 잃었고,$B$B가끔 우리가 다시 위대해질지 궁금해 하지만, 자엘라 같은 어린아이들은 이 오래된 뼈집에 희망을 줍니다."
rows["285:1782361362"]="난 지도자의 부담에 새롭다 나크랄의 부복을 지켜봐야 했지 대신 난 그의 엉망이 되는 걸 정리하고 있어$B$B가로쉬 펠스크림이 어떻게 하는지 모르겠지만, 그는 호드만큼 다양한 힘을 함께 유지할 수 있는 큰 힘을 가지고 있어야 합니다."
rows["285:2139572201"]="이 늑대와 얼음 거인은 매일 서로를 죽이면 무슨 상관이 있어?$B$B아니, 아니... 토림이 그의  ⁇ 을 벗어나 모든 동맹군들을 모아 울두어를 되찾으길 바란다.$B$B그가 이 일을 하지 않으면 세상은 갈라질 것이다!$B$B물론, 내가 당신에게 적절한 보상을 줄 것입니다."
rows["285:2142105029"]="귀신들이 마침내 쉬게 되는데, 곧 나도 다른 쪽으로 돌아갈 거야$B$B저는 여러분께 이 조언을 드리겠습니다. 판다리아는 역사의 땅입니다. 만약 여러분이 미래에 대해 불확실하다면, 여러분은 과거로부터 답을 찾아야 합니다.$B$B기억해두세요, 여기서 잘 살 수 있을 겁니다."
rows["285:282742886"]="이 소위 패러딘들은 나를 통과시키지 않을 것입니다. 그래서 전설적인 프레이즈 시아비의 유명한 담배가 스트라톨메에서 남아 있는지 볼 수 있습니다! 그들은 스컬지, 만약 당신이 나에게 물어보면.$B$B당신과 '나는' 사이에, 나는 그들의 '형제 빛'이건 속임수야, 내가 말해줄게"
rows["285:364702594"]="현재 우리는 스트라톨메의 이 반을 다시 통제하고 있고 그 때문에 기뻐해야 합니다. 은손의 옛 요새는 합법적인 소유자의 손에 돌아왔습니다."
rows["285:482330107"]="저같은 사람이 그 나무를 벌이는 이끼에게 잡히면, 당신은 정말 용감해 여기 오게 될 겁니다.\010하프스를 방해하고 내 연쇄를 깨면 내가 네 옆에 싸워줄게\010적의 눈을 깜빡이는 능력은 하프스의 광기 공격에 견딜 수 있도록 도와줄 거야"
rows["285:52715337"]="고령 마법사이자 학자인 다리네스는 도시의 가장 학문적인 고고학자이자 가장 사회적인 사람입니다.$B$B그녀는 종종 도시의 중심부 북쪽에 있는 Legerdemain Lounge에서 볼 수 있습니다. 분위기를 즐기고 또는 소유자와 고객과 그녀의 야생 모험을 논의하고 있습니다."
rows["285:656429166"]="북쪽에서 멀리 있는 썬더 블러프의 큰 집에서 식물학에 대해 가르쳐 줄 수 있는 곳도 있습니다. 마을 밖으로 가는 길을 따라 가서 블래프 밑에 엘리베이터를 타고 승강장 꼭대기에 올라갈 수 있습니다."
rows["285:736901369"]="이제 치유이 새로운 피를 보내야 할 때였어! 아쉽게도 이 모든 걸 헛되이 해왔어. 우리는 손님들을 위해 공연을 할 수 없습니다. 믿으실래요? 모러스는 새로운 공연을 시작하도록 금지하고, 그리고 내 후원자들은 미쳤어요."
rows["285:875053272"]="브루머 웬더브레, 당신들의 서비스로$b$b제드 숲을 여행해서 맥주에서 가장 좋은 재료만 찾아다니는 거요$b$b새벽의 꽃에 대한 고위하고 강력한 골든드래프트와 달리$b$b대량 생산을 위한 큰 맥주 공장도 있고, 술 마시는 것을 좋아하면 괜찮아요."
rows["286:1180856078"]=" ⁇ 초, 어? 못생긴 작은 악마가 지상에 15미터 정도 깊이 달려갑니다.$B$B풀의 뚜렷한 끝을 잡아서 다른 끝이 나올 때까지 계속 움직여라"
rows["286:156341073"]="얼라이언스의 모험적 인 조합들의 합동 노력 덕분에 우리는 우리가 필요로 할 것 같은 모든 노래한 석탄들을 수집할 수 있었습니다. 하지만, 다른 수집가들과 함께 확인해 볼 수도 있습니다."
rows["286:1826119800"]="밤 엘프들은 이 수족류를 가지고 있을 수 있고, 그냥 그리폰을 내 머리 속의 바람을 내놔!  \010이제 더 이상 못 지킬 거요, 거리스  ⁇ 든으로 가세요."
rows["286:241616235"]="이 땅에서 살던 우리 중 몇 명만이 엘루네의 스키타가 처음 지나갔고, 대부분 길네아스의 멸망으로 고통받았습니다.$B$B우리는 자연의 방법을 배우고 균형을 유지하기 위해 이 숲에 정착했습니다. 이 저주받은 땅에서, 우리의 저주받은 사람들은 새로운 삶의 방식을 발견했습니다."
rows["286:361062526"]="용사들이여, 살아 있었군! 십자군의 시험에서 상대를 모조리 때려눕혔을 뿐 아니라, 아서스의 계획을 방해하기까지 하다니! 그대들의 노련한 솜씨는 스컬지에 대항하는 강력한 무기가 될 걸세. 잘했네! 은빛십자군 마법사가 그대들을 지상으로 보내 줄 걸세!"
rows["286:485377315"]="\"오로기스트\"이란 무엇인가? 더 나은 질문은 \"오로기스트\"가 아닌 것\"이 아닐까? \"오로기스트\"라는 것은 모든 것을 연구한다는 뜻입니다! 사실, 저는 \"모든 것\"에 너무 잘 숙련되어 있습니다.$B$B미안해 내 내 내통자 말이지"
rows["286:651311757"]="무슨...?$b$b저는 그들을 불분명한 떠다니는 장애물이라고 부르고, 제가 사는 곳에서는 대부분 그들의 존재를 부정합니다.$b$b하지만 저는 더 잘 알고 있습니다. 저는 그들을 가까이에서 봤습니다. 최근 몇 년 동안 이 배를 건설하는데 사용했습니다."
rows["286:874414792"]="마을 사람들에게 사랑 표지판을 주면, 당신은 다른 선물을 받을 것입니다. 일부는 당신이 보관하고 사용하기를 원하지만 다른 것들은 묶어서 좋아하는 영웅에게 제공 될 수 있습니다! Kwee Q. Peddlefeet을 방문하여 그들을 돌려주십시오.$B$B케이 (Kwee) 는 카어네, 실바나스 (Sylvanas) 와 트랄 (Thall) 근처에서 발견된다."
rows["287:1107176117"]="검, 손톱, 칼, 물론, 저는 악당들을 훈련시켜서 모두 사용했습니다. 이제 악당, 저는 악당을 만지지 않을 것이고,$B$B ⁇ 은 거리는 숨기는 게 없어 그 길을 가면 큰 소음과 긴 청소를 당할 거야"
rows["287:1506343695"]="Jor Jor는 네 바람의 계곡에서 왔고, 농부의 아들로 태어났으며, 그가 온 것을 듣고 고향을 떠나서 이곳으로 왔습니다. 그는 자신을 전사라고 믿고 있지만, 저는 자신은 오만한 청년이라고 확신할 수 있습니다."
rows["287:1695959909"]="우리 삶의 길은 잠시만 교차하고 이제 우리들의 길은 갈라질 때가 되었습니다. 이 시간을 당신을 가르치는데 바쳤다고 생각하고, 이제 당신을 당신의 다음 멘토와 함께 길을 갈 수 있도록 보내겠습니다. 오그리마의 사루 스틸푸리를 찾아보세요. 그는 당신이 배워야 할 것을 가르쳐 줄 것입니다."
rows["287:174309465"]="내 최고의 발명품인 벤더 트론과 이야기해 1000그는 당신의 모든 필요를 가지고 있습니다. 칼림도어... 그의 프로그래밍은 협상할 수 없음을 말할 것도 없고, 당신이 보는 가격은 당신이 지불하는 가격입니다."
rows["287:258384188"]="저는 라더퍼드 트윈입니다. 아라티 연못에 배치된 디필러의 주요 공급자입니다. 저희와 함께 지위를 향상시키면서, 저는 여러분에게 유용한 상품들을 선별하게 하겠습니다."
rows["288:1239121139"]="오, 네, 제에 대한 거짓 소문이 많이 퍼져 있습니다. 제가 암흑성 요정에서 매력적으로 자랐다는 점, 다섯번째 생일에 한  ⁇ 을 사용해서 여섯 명의 악마를 죽였다는 점, 심지어는 -- 이것이 제가 가장 좋아하는 것인데요-- 저는 자연스러운 금발이라는 점입니다. 사람들은 무엇이든 믿으실 겁니다."
rows["288:1286006865"]="그럼 스프링스파이드 피즈레거를 찾고 있어요. 왜 그 작은 기둥과 그 기기가... 내가 말해줄게, 만약 당신이 기술공 타운에 있는 그의 가게로 가면,  \010폭발하는 양... 왜 그런 걸 만들지?"
rows["288:1300968063"]="네 첫 번째 운동은 언더시티내... 상관없어 언더시티 헐적의 뒤쪽으로 가 로데론 브릴 남쪽에서 엘리베이터를 타고 내려가 언더시티 더 많은 도움을 요청할 수 있는 보호자들이 있습니다."
rows["288:1473318608"]="오, 그래, 그래서 오크들이 윈저와 윈저를 몰아냈어요. 그는 한 인치도 움직이지 않았습니다. 그들은 그를 고소했습니다. 10개씩."
rows["288:1671849450"]="이제 전쟁이 곧 일어날 것이고 남은 것은 모든 물품과 무기를 실리투스 센라리온 포크로 보내야 할 것이며, 그 다음에는 용감한 영혼이"
rows["288:1760608340"]="안녕하세요, 저는 호랑이입니다. 이명박군과 제 동생은 아제로스 야생하고 무관한 경주를 탐험하는 건 흥미롭지만 이번에는 너무 흥분됐어"
rows["288:2071768871"]="비행할 곳이 어디든? 당신은 언더시티로 가야 할 것입니다! 마을 밖으로 도로에서 남쪽으로 이동하고, 남서쪽으로 로데론의 망물]로 이동하십시오. 당신은 망물 뒤에서 엘리베이터를 타고 언더시티로 내려갈 수 있으며, 거기에있을 때 더 구체적인 방향을 요청 언더시티 수호자"
rows["288:570304576"]="솔직히 제가 쉐도파에 합류한 것에 놀랐어요. 놀랍지 않은 집단이 아니었거든요.$B$B왜 그들과 함께 했는지 기억하는데 난리가 없어요. 안지도 설득력이 있다고 합시다."
rows["288:893934564"]="마루카스는 이 숲의 역사적 중요성에 대해 끊임없이 이야기하지만, 현재의 문제들이 해결되기 전까지는 역사에 빠져들게 될 여유가 없습니다.$B$B그의 일은 중요하지 않다고 말하는 건 아니지만, 누가 수호관리와 물류를 관리해야 합니다."
rows["288:951673045"]="아라토르 동맹이 아라티 계곡에서 해보고 있는 일은 존경할 만한 일입니다. 호드 친구들이 길을 막고 있어 스톰윈드 핫셰임 여인이 왕실에서 당신을 기다리고 있어 아라티 계곡으로 데려갈 수 있어요"
rows["289:103889637"]="일부 사우르 사제들은 나를 배신자라고 부르고 \"크로시크는 바다에서 사냥하지 않는다\"고 말한다.$b$b크로스의 길을 따라가지만, 이 사제들과는 동의하지 않습니다. 크로시크는 어디든 사냥합니다.$b$b이 사제들과 그들의 거저하고 폐쇄적인 크로시크의 생각은 오늘날의 스쿠머블레이드에서 자리잡지 않습니다."
rows["289:1111234035"]="내가 보는 것은 침략의 전초라고$B$B네, 마스터가 포털을 봉쇄하는 데 현명했지만 그 이후로 그의... 어떻게 말해야 할까요?$B$B이 손실로 레지온은 기회를 잡았습니다. 그들은 이제 빠져나가고 있습니다."
rows["289:1484706881"]="들어, 우리가 탈출한 이후로 축하 술 한 잔을 마시고 있어$b$b우리를  ⁇ 은 작은 사람들은 법 앞에  ⁇ 어야 합니다!$b$b만약 뭔가 안되더라도, 이 곳에 발을 디딘 모든 의심의 여지가 없는 탐험가들은 노예로 팔릴 것입니다."
rows["289:158280114"]="정말 수강인이 어디 있는지 묻고 있는거야? 당신은 위대한 도형에 대해 들어본 적이 없나? 우리의 최고의 수강사들은 모두 그들의 무기와 갑옷을 만들기 위해 거기에 모여있다!  \010아이언포지 중간에 거의 죽고 있습니다. 그리고 거기서 가장 뛰어난 수강사 중 한 명인 뱅거스 딥포리지를 찾을 것입니다.  "
rows["289:1662982931"]="물론 수도원입니다!$b$b천안 수도원에서 온 승려들은 저처럼 젊은 판다레들에게 싸우는 법을 가르치는 전문성을 가지고 있습니다. 위대한 전투가 모두 이곳에서 시작되었습니다.$b$b전설이 그렇게 말하는 것 같아요"
rows["289:1691821247"]="저는  ⁇ 이산 시리시드 스나크의 수익성 (허가 수료) 를 조사하던 중  ⁇ 이산 사이에 찢어진 카트를 발견했습니다. \"하이, 무료 카트!\" 즉, 여러분이 본 가장 큰 바실리스크가 나타나기 전까지, 저는 그 모든 것을 뒤로 남겨두어야 했습니다."
rows["289:1935093694"]="저는 그것을 이해할 수 있습니다. 하지만 왕은 변화를 허용했습니다. 기둥이 바구니에 탭을 해줬습니다. 그래서 새로운 종류의 문제에 대해 일할 기회가 생겼습니다. 어떻게 효율적이고 빠르게 바구니를 열고 그 내용을 배포할 수 있는지요."
rows["289:2022017328"]="어 ⁇ 든, 이게 바로 문제입니다. 이 모든 생물들은 아무데서나 생겨나고 통제를 벗어난 채 달리고 있습니다. 그리고 마지스터와 그의 연습생들은 어디로 도망쳤을까요? \"Wyllithen, 안녕하세요, 당신은 함께 가고 싶습니까?\"$B$B용기가 있어!"
rows["289:2089579092"]="네 손에는 나가 피가 있다면 내 동맹자야$b$b오래전, 다시는 누구의 노예가 되지 않겠다고 맹세했고, 이드라케스가 우리를 잡기 전까지 그 협상을 지켜봤어요. 이제 분노를 억제할 수 없어요."
rows["289:98921156"]="모든 수집이 완료되고 완성된 상품은 실리투스로 배송되고 있습니다. 마치고 있는 것처럼 보입니다. 하루도 채 되지 않아서 전부가 거기까지 도착합니다. 그 후에 우리는 단지 누군가에게  ⁇ 을 울리고 아안키라지 문들을 열어야 합니다. 그러면 진짜 재미는 시작됩니다."
rows["289:998260934"]="호바트랑 저는 가야미트 마감에 대비할 수 있는 멋진 백업 제품을 준비하고 있습니다$B$B채굴에서 남은 것은 너무 많고, 사라지면 카자콜라가 모두 함께 갈 것 같아요."
rows["28:1003159375"]="이 고드프레를 위해 돈을 지불할 거야!"
rows["28:100786608"]="내 수영장에 들어올 수 있겠어?"
rows["28:1008845006"]="...그게 무슨 소리인지 모르겠어"
rows["28:1013313564"]="위켓은 바-배메드 될 거야!"
rows["28:1013935765"]="내가 뭘 도와줄 수 있어?"
rows["28:1014171979"]="뭘 배우고 싶니?"
rows["28:1017346419"]="이곳에 오지 말아야 했어..."
rows["28:1020032870"]="위에 가면... 몸조심해라."
rows["28:1020819347"]="문제가 될 수도 있어요"
rows["28:1023375835"]="<그 주머니를  ⁇ 어봐>"
rows["28:1025639722"]="잘 됐어요, 엘리 씨를 계속 하세요"
rows["28:1028575348"]=" ⁇ 은... 당신을 데려갈거야..."
rows["28:1029617636"]="난 널 덩굴로 만들겠어!"
rows["28:1029696699"]="오크와 트롤, 어디든!"
rows["28:1030566717"]="내 애완 동물에 대해 어떻게 생각하십니까?"
